1	//! Block compression for 128-document segments.
2	//!
3	//! Documents are accumulated into 128-doc blocks, compressed as a unit,
4	//! then emitted with a fixed header. Readers decompress on demand with
5	//! random access by block index.
6	
7	use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
8	use std::io::{Cursor, Read, Write};
9	use xerj_common::XerjError;
10	
11	use crate::codec::{get_codec, Codec, CompressionLevel};
12	
13	/// Result alias for block operations.
14	pub type Result<T> = std::result::Result<T, XerjError>;
15	
16	/// Number of documents per compressed block.
17	pub const BLOCK_SIZE: usize = 128;
18	
19	/// Magic bytes at the start of every block header.
20	const BLOCK_MAGIC: u32 = 0x5A424C4B; // "ZBLK"
21	
22	// ─────────────────────────────────────────────────────────────────────────────
23	// Block header on-disk layout (20 bytes)
24	// ─────────────────────────────────────────────────────────────────────────────
25	//
26	//  Offset  Size  Field
27	//  ──────  ────  ─────────────────────────────
28	//       0     4  magic (ZBLK)
29	//       4     4  doc_count   (u32 LE)
30	//       8     4  uncompressed_len (u32 LE)
31	//      12     4  compressed_len   (u32 LE)
32	//      16     1  codec_id    (0=none, 1=lz4, 2=zstd)
33	//      17     3  reserved
34	// ─────────────────────────────────────────────────────────────────────────────
35	
36	#[derive(Debug, Clone)]
37	pub struct BlockHeader {
38	    pub doc_count: u32,
39	    pub uncompressed_len: u32,
40	    pub compressed_len: u32,
41	    pub codec_id: u8,
42	}
43	
44	impl BlockHeader {
45	    pub const SIZE: usize = 20;
46	
47	    fn codec_id_for(level: CompressionLevel) -> u8 {
48	        match level {
49	            CompressionLevel::None => 0,
50	            CompressionLevel::Fast => 1,
51	            CompressionLevel::Balanced | CompressionLevel::Best => 2,
52	        }
53	    }
54	
55	    fn write_to(&self, out: &mut impl Write) -> std::io::Result<()> {
56	        out.write_u32::<LittleEndian>(BLOCK_MAGIC)?;
57	        out.write_u32::<LittleEndian>(self.doc_count)?;
58	        out.write_u32::<LittleEndian>(self.uncompressed_len)?;
59	        out.write_u32::<LittleEndian>(self.compressed_len)?;
60	        out.write_u8(self.codec_id)?;
61	        out.write_all(&[0u8; 3])?; // reserved
62	        Ok(())
63	    }
64	
65	    fn read_from(r: &mut impl Read) -> std::io::Result<Self> {
66	        let magic = r.read_u32::<LittleEndian>()?;
67	        if magic != BLOCK_MAGIC {
68	            return Err(std::io::Error::new(
69	                std::io::ErrorKind::InvalidData,
70	                format!("bad block magic: 0x{magic:08X}"),
71	            ));
72	        }
73	        let doc_count = r.read_u32::<LittleEndian>()?;
74	        let uncompressed_len = r.read_u32::<LittleEndian>()?;
75	        let compressed_len = r.read_u32::<LittleEndian>()?;
76	        let codec_id = r.read_u8()?;
77	        let mut _reserved = [0u8; 3];
78	        r.read_exact(&mut _reserved)?;
79	        Ok(Self {
80	            doc_count,
81	            uncompressed_len,
82	            compressed_len,
83	            codec_id,
84	        })
85	    }
86	}
87	
88	// ─────────────────────────────────────────────────────────────────────────────
89	// BlockWriter
90	// ─────────────────────────────────────────────────────────────────────────────
91	
92	/// Accumulates raw serialized documents and emits compressed blocks of
93	/// [`BLOCK_SIZE`] documents each.
94	pub struct BlockWriter {
95	    codec: Box<dyn Codec>,
96	    codec_id: u8,
97	    #[allow(dead_code)]
98	    level: CompressionLevel,
99	    /// Length-prefixed raw document payloads for the current block.
100	    pending: Vec<u8>,
101	    pending_count: u32,
102	    /// Completed, compressed blocks ready for flushing.
103	    completed: Vec<u8>,
104	}
105	
106	impl BlockWriter {
107	    pub fn new(level: CompressionLevel) -> Self {
108	        let codec_id = BlockHeader::codec_id_for(level);
109	        Self {
110	            codec: get_codec(level),
111	            codec_id,
112	            level,
113	            pending: Vec::new(),
114	            pending_count: 0,
115	            completed: Vec::new(),
116	        }
117	    }
118	
119	    /// Add a serialized document to the current block.
120	    ///
121	    /// Each document is length-prefixed (u32 LE) inside the block payload so
122	    /// that individual records can be located after decompression.
123	    pub fn add_document(&mut self, doc: &[u8]) -> Result<()> {
124	        // Length prefix
125	        let len = doc.len() as u32;
126	        self.pending
127	            .write_u32::<LittleEndian>(len)
128	            .map_err(|e| XerjError::internal(e.to_string()))?;
129	        self.pending.extend_from_slice(doc);
130	        self.pending_count += 1;
131	
132	        if self.pending_count as usize >= BLOCK_SIZE {
133	            self.flush_block()?;
134	        }
135	        Ok(())
136	    }
137	
138	    /// Flush any remaining documents as a partial block.
139	    pub fn finish(&mut self) -> Result<Vec<u8>> {
140	        if self.pending_count > 0 {
141	            self.flush_block()?;
142	        }
143	        Ok(std::mem::take(&mut self.completed))
144	    }
145	
146	    fn flush_block(&mut self) -> Result<()> {
147	        let raw = std::mem::take(&mut self.pending);
148	        let uncompressed_len = raw.len() as u32;
149	        let doc_count = self.pending_count;
150	        self.pending_count = 0;
151	
152	        let compressed = self.codec.compress(&raw)?;
153	        let compressed_len = compressed.len() as u32;
154	
155	        let header = BlockHeader {
156	            doc_count,
157	            uncompressed_len,
158	            compressed_len,
159	            codec_id: self.codec_id,
160	        };
161	        header
162	            .write_to(&mut self.completed)
163	            .map_err(|e| XerjError::internal(e.to_string()))?;
164	        self.completed.extend_from_slice(&compressed);
165	        Ok(())
166	    }
167	}
168	
169	// ─────────────────────────────────────────────────────────────────────────────
170	// BlockReader
171	// ─────────────────────────────────────────────────────────────────────────────
172	
173	/// Reads compressed blocks written by [`BlockWriter`].
174	///
175	/// Decompression is lazy — only happens when [`next_block`] is called.
176	pub struct BlockReader<'a> {
177	    cursor: Cursor<&'a [u8]>,
178	}
179	
180	impl<'a> BlockReader<'a> {
181	    pub fn new(data: &'a [u8]) -> Self {
182	        Self {
183	            cursor: Cursor::new(data),
184	        }
185	    }
186	
187	    /// Read and decompress the next block, returning individual documents.
188	    ///
189	    /// Returns `None` when all blocks have been consumed.
190	    pub fn next_block(&mut self) -> Result<Option<Vec<Vec<u8>>>> {
191	        if self.cursor.position() as usize >= self.cursor.get_ref().len() {
192	            return Ok(None);
193	        }
194	
195	        let header = BlockHeader::read_from(&mut self.cursor)
196	            .map_err(|e| XerjError::internal(format!("block header read: {e}")))?;
197	
198	        let mut compressed = vec![0u8; header.compressed_len as usize];
199	        self.cursor
200	            .read_exact(&mut compressed)
201	            .map_err(|e| XerjError::internal(format!("block data read: {e}")))?;
202	
203	        // Select decompressor by codec_id
204	        let decompressed = match header.codec_id {
205	            0 => {
206	                // None
207	                if compressed.len() != header.uncompressed_len as usize {
208	                    return Err(XerjError::internal("None codec length mismatch"));
209	                }
210	                compressed
211	            }
212	            1 => {
213	                // LZ4
214	                lz4_flex::decompress_size_prepended(&compressed)
215	                    .map_err(|e| XerjError::internal(format!("LZ4 decompress: {e}")))?
216	            }
217	            2 => {
218	                // Zstd
219	                zstd::bulk::decompress(&compressed, header.uncompressed_len as usize)
220	                    .map_err(|e| XerjError::internal(format!("Zstd decompress: {e}")))?
221	            }
222	            id => return Err(XerjError::internal(format!("unknown codec_id: {id}"))),
223	        };
224	
225	        // Split individual documents by length prefix
226	        let mut docs = Vec::with_capacity(header.doc_count as usize);
227	        let mut rdr = Cursor::new(decompressed);
228	        for _ in 0..header.doc_count {
229	            let len = rdr
230	                .read_u32::<LittleEndian>()
231	                .map_err(|e| XerjError::internal(format!("doc len read: {e}")))?
232	                as usize;
233	            let mut doc = vec![0u8; len];
234	            rdr.read_exact(&mut doc)
235	                .map_err(|e| XerjError::internal(format!("doc data read: {e}")))?;
236	            docs.push(doc);
237	        }
238	
239	        Ok(Some(docs))
240	    }
241	
242	    /// Collect all documents from all blocks.
243	    pub fn read_all(&mut self) -> Result<Vec<Vec<u8>>> {
244	        let mut all = Vec::new();
245	        while let Some(block) = self.next_block()? {
246	            all.extend(block);
247	        }
248	        Ok(all)
249	    }
250	}
