1	//! Compression codecs: LZ4, Zstd, and passthrough.
2	
3	use xerj_common::config::CompressionLevel as ConfigLevel;
4	use xerj_common::XerjError;
5	
6	/// Result alias for codec operations.
7	pub type Result<T> = std::result::Result<T, XerjError>;
8	
9	// ─────────────────────────────────────────────────────────────────────────────
10	// Trait
11	// ─────────────────────────────────────────────────────────────────────────────
12	
13	/// A stateless, thread-safe compression/decompression codec.
14	pub trait Codec: Send + Sync {
15	    /// Compress `data` and return the compressed bytes.
16	    fn compress(&self, data: &[u8]) -> Result<Vec<u8>>;
17	
18	    /// Decompress `data` into a buffer of exactly `output_len` bytes.
19	    ///
20	    /// `output_len` must match the original uncompressed length.
21	    fn decompress(&self, data: &[u8], output_len: usize) -> Result<Vec<u8>>;
22	
23	    /// Human-readable name of this codec.
24	    fn name(&self) -> &'static str;
25	}
26	
27	// ─────────────────────────────────────────────────────────────────────────────
28	// Compression level
29	// ─────────────────────────────────────────────────────────────────────────────
30	
31	/// Selects the compression algorithm and effort level for the block codecs in
32	/// this crate.
33	///
34	/// Not the operator-facing type: `compression.level` in the config file
35	/// deserialises into [`xerj_common::config::CompressionLevel`], which has no
36	/// `None` variant and lives in a crate below this one in the dependency graph.
37	/// The two stay in step because the zstd effort each name means is defined
38	/// once, in that enum's `zstd_level`, and [`ZstdCodec::balanced`] /
39	/// [`ZstdCodec::best`] read it from there.
40	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
41	pub enum CompressionLevel {
42	    /// No compression — raw bytes pass through unchanged.
43	    None,
44	    /// LZ4: very fast compression with moderate ratio.
45	    #[default]
46	    Fast,
47	    /// Zstd at the `"balanced"` effort level.
48	    Balanced,
49	    /// Zstd at the `"best"` effort level.
50	    Best,
51	}
52	
53	impl CompressionLevel {
54	    /// Parse from a string (case-insensitive).
55	    ///
56	    /// Named `from_str` for config ergonomics; returns `Option` (not the
57	    /// `Result` that `std::str::FromStr` requires), so it deliberately does
58	    /// not implement that trait.
59	    #[allow(clippy::should_implement_trait)]
60	    pub fn from_str(s: &str) -> Option<Self> {
61	        match s.to_ascii_lowercase().as_str() {
62	            "none" => Some(Self::None),
63	            "fast" => Some(Self::Fast),
64	            "balanced" => Some(Self::Balanced),
65	            "best" => Some(Self::Best),
66	            _ => None,
67	        }
68	    }
69	}
70	
71	// ─────────────────────────────────────────────────────────────────────────────
72	// NoneCodec — passthrough
73	// ─────────────────────────────────────────────────────────────────────────────
74	
75	/// Passthrough codec — no compression applied.
76	#[derive(Debug, Default, Clone)]
77	pub struct NoneCodec;
78	
79	impl Codec for NoneCodec {
80	    fn compress(&self, data: &[u8]) -> Result<Vec<u8>> {
81	        Ok(data.to_vec())
82	    }
83	
84	    fn decompress(&self, data: &[u8], output_len: usize) -> Result<Vec<u8>> {
85	        if data.len() != output_len {
86	            return Err(XerjError::internal(format!(
87	                "NoneCodec: expected {output_len} bytes, got {}",
88	                data.len()
89	            )));
90	        }
91	        Ok(data.to_vec())
92	    }
93	
94	    fn name(&self) -> &'static str {
95	        "none"
96	    }
97	}
98	
99	// ─────────────────────────────────────────────────────────────────────────────
100	// Lz4Codec
101	// ─────────────────────────────────────────────────────────────────────────────
102	
103	/// LZ4-based codec wrapping [`lz4_flex`].
104	#[derive(Debug, Default, Clone)]
105	pub struct Lz4Codec;
106	
107	impl Codec for Lz4Codec {
108	    fn compress(&self, data: &[u8]) -> Result<Vec<u8>> {
109	        // lz4_flex::compress_prepend_size returns Vec<u8> (not a Result)
110	        Ok(lz4_flex::compress_prepend_size(data))
111	    }
112	
113	    fn decompress(&self, data: &[u8], _output_len: usize) -> Result<Vec<u8>> {
114	        lz4_flex::decompress_size_prepended(data)
115	            .map_err(|e| XerjError::internal(format!("LZ4 decompress: {e}")))
116	    }
117	
118	    fn name(&self) -> &'static str {
119	        "lz4"
120	    }
121	}
122	
123	// ─────────────────────────────────────────────────────────────────────────────
124	// ZstdCodec
125	// ─────────────────────────────────────────────────────────────────────────────
126	
127	/// Zstd-based codec wrapping the [`zstd`] crate.
128	#[derive(Debug, Clone)]
129	pub struct ZstdCodec {
130	    /// Zstd compression level, from
131	    /// [`xerj_common::config::CompressionLevel::zstd_level`].
132	    level: i32,
133	}
134	
135	impl ZstdCodec {
136	    pub fn new(level: i32) -> Self {
137	        Self { level }
138	    }
139	
140	    /// Balanced Zstd — the level `compression.level = "balanced"` selects.
141	    pub fn balanced() -> Self {
142	        Self::new(ConfigLevel::Balanced.zstd_level())
143	    }
144	
145	    /// Maximum-ratio Zstd — the level `compression.level = "best"` selects.
146	    ///
147	    /// This used to be a hardcoded 19 while the config surface's own enum
148	    /// documented 19 too and neither reached an encoder (#318). Both now read
149	    /// the same table, so "best" cannot mean one thing to an operator and
150	    /// another to a codec; see [`ConfigLevel`] for why the measured answer is
151	    /// 6 rather than 19.
152	    pub fn best() -> Self {
153	        Self::new(ConfigLevel::Best.zstd_level())
154	    }
155	}
156	
157	impl Default for ZstdCodec {
158	    fn default() -> Self {
159	        Self::balanced()
160	    }
161	}
162	
163	impl Codec for ZstdCodec {
164	    fn compress(&self, data: &[u8]) -> Result<Vec<u8>> {
165	        zstd::bulk::compress(data, self.level)
166	            .map_err(|e| XerjError::internal(format!("Zstd compress: {e}")))
167	    }
168	
169	    fn decompress(&self, data: &[u8], output_len: usize) -> Result<Vec<u8>> {
170	        zstd::bulk::decompress(data, output_len)
171	            .map_err(|e| XerjError::internal(format!("Zstd decompress: {e}")))
172	    }
173	
174	    fn name(&self) -> &'static str {
175	        "zstd"
176	    }
177	}
178	
179	// ─────────────────────────────────────────────────────────────────────────────
180	// Factory
181	// ─────────────────────────────────────────────────────────────────────────────
182	
183	/// Return a boxed codec appropriate for the given compression level.
184	pub fn get_codec(level: CompressionLevel) -> Box<dyn Codec> {
185	    match level {
186	        CompressionLevel::None => Box::new(NoneCodec),
187	        CompressionLevel::Fast => Box::new(Lz4Codec),
188	        CompressionLevel::Balanced => Box::new(ZstdCodec::balanced()),
189	        CompressionLevel::Best => Box::new(ZstdCodec::best()),
190	    }
191	}
