199	    use super::*;
200	
201	    const PAYLOAD: &[u8] = b"hello world this is a test payload that should compress well \
202	        because it has repeated patterns repeated patterns repeated patterns";
203	
204	    #[test]
205	    fn none_roundtrip() {
206	        let codec = NoneCodec;
207	        let compressed = codec.compress(PAYLOAD).unwrap();
208	        let decompressed = codec.decompress(&compressed, PAYLOAD.len()).unwrap();
209	        assert_eq!(decompressed, PAYLOAD);
210	    }
211	
212	    #[test]
213	    fn lz4_roundtrip() {
214	        let codec = Lz4Codec;
215	        let compressed = codec.compress(PAYLOAD).unwrap();
216	        let decompressed = codec.decompress(&compressed, PAYLOAD.len()).unwrap();
217	        assert_eq!(decompressed, PAYLOAD);
218	    }
219	
220	    #[test]
221	    fn lz4_reduces_size() {
222	        let codec = Lz4Codec;
223	        let compressed = codec.compress(PAYLOAD).unwrap();
224	        assert!(
225	            compressed.len() < PAYLOAD.len(),
226	            "LZ4 should compress repetitive data"
227	        );
228	    }
229	
230	    #[test]
231	    fn zstd_balanced_roundtrip() {
232	        let codec = ZstdCodec::balanced();
233	        let compressed = codec.compress(PAYLOAD).unwrap();
234	        let decompressed = codec.decompress(&compressed, PAYLOAD.len()).unwrap();
235	        assert_eq!(decompressed, PAYLOAD);
236	    }
237	
238	    #[test]
239	    fn zstd_best_roundtrip() {
240	        let codec = ZstdCodec::best();
241	        let compressed = codec.compress(PAYLOAD).unwrap();
242	        let decompressed = codec.decompress(&compressed, PAYLOAD.len()).unwrap();
243	        assert_eq!(decompressed, PAYLOAD);
244	    }
245	
246	    #[test]
247	    fn get_codec_factory() {
248	        for level in [
249	            CompressionLevel::None,
250	            CompressionLevel::Fast,
251	            CompressionLevel::Balanced,
252	            CompressionLevel::Best,
253	        ] {
254	            let codec = get_codec(level);
255	            let compressed = codec.compress(PAYLOAD).unwrap();
256	            let decompressed = codec.decompress(&compressed, PAYLOAD.len()).unwrap();
257	            assert_eq!(decompressed, PAYLOAD, "roundtrip failed for {level:?}");
