519	    /// Build a [`FieldEncoding::UrlTemplate`] from a column of URL path strings.
520	    pub fn encode_as_url_template(&self, values: &[&str]) -> FieldEncoding {
521	        let mut templates: Vec<String> = Vec::new();
522	        let mut tmpl_index: HashMap<String, u16> = HashMap::new();
523	        let mut template_ids: Vec<u16> = Vec::with_capacity(values.len());
524	        let mut variables: Vec<Vec<String>> = Vec::with_capacity(values.len());
525	
526	        for v in values {
527	            let (tmpl, vars) = extract_url_template(v);
528	            let id = if let Some(&existing) = tmpl_index.get(&tmpl) {
529	                existing
530	            } else {
531	                let id = templates.len() as u16;
532	                tmpl_index.insert(tmpl.clone(), id);
533	                templates.push(tmpl);
534	                id
535	            };
536	            template_ids.push(id);
537	            variables.push(vars);
538	        }
539	
540	        FieldEncoding::UrlTemplate {
541	            templates,
542	            template_ids,
543	            variables,
544	        }
545	    }
