556	    /// Build a [`FieldEncoding::Dictionary`] from a column of strings.
557	    pub fn encode_as_dictionary(&self, values: &[&str]) -> FieldEncoding {
558	        let mut dict: Vec<String> = Vec::new();
559	        let mut dict_index: HashMap<&str, u16> = HashMap::new();
560	        let mut ids: Vec<u16> = Vec::with_capacity(values.len());
561	
562	        for v in values {
563	            let id = if let Some(&existing) = dict_index.get(v) {
564	                existing
565	            } else {
566	                let id = dict.len() as u16;
567	                dict_index.insert(v, id);
568	                dict.push(v.to_string());
569	                id
570	            };
571	            ids.push(id);
572	        }
573	
574	        FieldEncoding::Dictionary { dict, ids }
575	    }
