699	/// Parse a timestamp string to microseconds since the Unix epoch.
700	///
701	/// Returns `None` on parse failure — callers substitute `0` as a sentinel.
702	fn parse_timestamp_us(v: &str, format: &TimestampFormat) -> Option<i64> {
703	    let v = v.trim();
704	    match format {
705	        TimestampFormat::EpochSeconds => v.parse::<i64>().ok().map(|s| s * 1_000_000),
706	        TimestampFormat::EpochMillis => v.parse::<i64>().ok().map(|ms| ms * 1_000),
707	        TimestampFormat::Iso8601 => parse_iso8601_us(v),
708	        TimestampFormat::ApacheCommon => parse_apache_us(v),
709	        TimestampFormat::NginxDefault => parse_nginx_us(v),
710	        TimestampFormat::Custom(_) => None,
711	    }
712	}
713	
714	/// Minimal ISO 8601 parser → microseconds since epoch.
715	///
716	/// Handles `YYYY-MM-DDTHH:MM:SSZ` and `YYYY-MM-DDTHH:MM:SS+HH:MM`.
717	fn parse_iso8601_us(v: &str) -> Option<i64> {
718	    // Expect at least "YYYY-MM-DDTHH:MM:SS"
719	    if v.len() < 19 {
720	        return None;
721	    }
722	    let year: i64 = v.get(0..4)?.parse().ok()?;
723	    let month: i64 = v.get(5..7)?.parse().ok()?;
724	    let day: i64 = v.get(8..10)?.parse().ok()?;
725	    let hour: i64 = v.get(11..13)?.parse().ok()?;
726	    let min: i64 = v.get(14..16)?.parse().ok()?;
727	    let sec: i64 = v.get(17..19)?.parse().ok()?;
728	
729	    // Timezone offset
730	    let tz_offset_secs: i64 = if v.len() > 19 {
731	        let tz = v.get(19..)?;
732	        if tz.starts_with('Z') || tz.starts_with('z') {
733	            0
734	        } else if (tz.starts_with('+') || tz.starts_with('-')) && tz.len() >= 6 {
735	            let sign: i64 = if tz.starts_with('-') { -1 } else { 1 };
736	            let th: i64 = tz.get(1..3)?.parse().ok()?;
737	            let tm: i64 = tz.get(4..6)?.parse().ok()?;
738	            sign * (th * 3600 + tm * 60)
739	        } else {
740	            0
741	        }
742	    } else {
743	        0
744	    };
745	
746	    let days = days_since_epoch(year, month, day)?;
747	    let secs = days * 86400 + hour * 3600 + min * 60 + sec - tz_offset_secs;
748	    Some(secs * 1_000_000)
749	}
750	
751	/// Apache Common Log format: `[10/Jan/2024:12:34:56 +0000]`
752	fn parse_apache_us(v: &str) -> Option<i64> {
753	    // Strip brackets
754	    let v = v.trim_matches(|c| c == '[' || c == ']').trim();
755	    // "10/Jan/2024:12:34:56 +0000"
756	    if v.len() < 26 {
757	        return None;
758	    }
759	    let day: i64 = v.get(0..2)?.parse().ok()?;
760	    let month_str = v.get(3..6)?;
761	    let month = month_from_abbr(month_str)?;
762	    let year: i64 = v.get(7..11)?.parse().ok()?;
763	    let hour: i64 = v.get(12..14)?.parse().ok()?;
764	    let min: i64 = v.get(15..17)?.parse().ok()?;
765	    let sec: i64 = v.get(18..20)?.parse().ok()?;
766	
767	    let tz_offset_secs: i64 = if v.len() >= 26 {
768	        let tz = v.get(21..)?.trim();
769	        if tz.len() >= 5 {
770	            let sign: i64 = if tz.starts_with('-') { -1 } else { 1 };
771	            let th: i64 = tz.get(1..3)?.parse().ok()?;
772	            let tm: i64 = tz.get(3..5)?.parse().ok()?;
773	            sign * (th * 3600 + tm * 60)
774	        } else {
775	            0
776	        }
777	    } else {
778	        0
779	    };
780	
781	    let days = days_since_epoch(year, month, day)?;
782	    let secs = days * 86400 + hour * 3600 + min * 60 + sec - tz_offset_secs;
783	    Some(secs * 1_000_000)
784	}
785	
786	/// Nginx default log format: `2024/01/15 12:34:56`
787	fn parse_nginx_us(v: &str) -> Option<i64> {
788	    if v.len() < 19 {
789	        return None;
790	    }
791	    let year: i64 = v.get(0..4)?.parse().ok()?;
792	    let month: i64 = v.get(5..7)?.parse().ok()?;
793	    let day: i64 = v.get(8..10)?.parse().ok()?;
794	    let hour: i64 = v.get(11..13)?.parse().ok()?;
795	    let min: i64 = v.get(14..16)?.parse().ok()?;
796	    let sec: i64 = v.get(17..19)?.parse().ok()?;
797	
798	    let days = days_since_epoch(year, month, day)?;
799	    let secs = days * 86400 + hour * 3600 + min * 60 + sec;
800	    Some(secs * 1_000_000)
801	}
