820	/// 3-letter month abbreviation → 1-based month number.
821	fn month_from_abbr(s: &str) -> Option<i64> {
822	    match s {
823	        "Jan" => Some(1),
824	        "Feb" => Some(2),
825	        "Mar" => Some(3),
826	        "Apr" => Some(4),
827	        "May" => Some(5),
828	        "Jun" => Some(6),
829	        "Jul" => Some(7),
830	        "Aug" => Some(8),
831	        "Sep" => Some(9),
832	        "Oct" => Some(10),
833	        "Nov" => Some(11),
834	        "Dec" => Some(12),
835	        _ => None,
836	    }
837	}
