887	
888	/// Split a URL path into a (template, variables) pair.
889	///
890	/// Numeric segments and UUID-like segments are replaced with `{}`.
891	///
892	/// ```
893	/// // "/api/users/123" → ("/api/users/{}", ["123"])
894	/// // "/static/js/app.abc123.js" → ("/static/js/{}", ["app.abc123.js"])
895	/// ```
896	fn extract_url_template(url: &str) -> (String, Vec<String>) {
897	    // Split off query string and fragment
898	    let path = url
899	        .split('?')
900	        .next()
901	        .unwrap_or(url)
902	        .split('#')
903	        .next()
904	        .unwrap_or(url);
905	
906	    let mut template_parts: Vec<&str> = Vec::new();
907	    let mut vars: Vec<String> = Vec::new();
908	
909	    for segment in path.split('/') {
910	        if is_variable_segment(segment) {
911	            template_parts.push("{}");
912	            vars.push(segment.to_string());
913	        } else {
914	            template_parts.push(segment);
915	        }
916	    }
917	
918	    (template_parts.join("/"), vars)
919	}
