996	/// Count the number of unique values in a slice.
997	pub fn unique_count(values: &[&str]) -> usize {
998	    values.iter().collect::<HashSet<_>>().len()
999	}
1000	
1001	/// Number of bytes required to encode `v` as an unsigned varint (LEB128).
1002	fn varint_unsigned_len(mut v: u64) -> usize {
1003	    if v == 0 {
1004	        return 1;
1005	    }
1006	    let mut len = 0;
1007	    while v > 0 {
1008	        len += 1;
1009	        v >>= 7;
1010	    }
1011	    len
1012	}
1013	
1014	/// Number of bytes required to encode `v` as a signed zigzag varint.
1015	fn varint_signed_len(v: i64) -> usize {
1016	    // Zigzag encode: (v << 1) ^ (v >> 63)
1017	    let encoded = ((v << 1) ^ (v >> 63)) as u64;
1018	    varint_unsigned_len(encoded)
1019	}
