1241	                let other_idx = values.iter().position(|v| v == "__other__").unwrap();
1242	                let other_bits: u32 = bitmap[other_idx].iter().map(|b| b.count_ones()).sum();
1243	                assert_eq!(
1244	                    other_bits as usize,
1245	                    refs.len() - 15,
1246	                    "the 5 values beyond the top-15 must land in __other__"
1247	                );
1248	            }
1249	            other => panic!(
1250	                "expected BitsetEnum, got {:?}",
