1553	            .collect();
1554	        let path_refs: Vec<&str> = paths.iter().map(String::as_str).collect();
1555	
1556	        let sizes: Vec<String> = (0..n)
1557	            .map(|i| (512 + (i * 137) % 65536).to_string())
1558	            .collect();
1559	        let size_refs: Vec<&str> = sizes.iter().map(String::as_str).collect();
1560	
1561	        let analyzer = FieldAnalyzer::new(1024);
1562	
1563	        let status_enc = analyzer.analyze("status", &statuses);
1564	        let method_enc = analyzer.analyze("method", &methods);
1565	        let ip_enc = analyzer.analyze("client_ip", &ip_refs);
1566	        let ts_enc = analyzer.analyze("@timestamp", &ts_refs);
1567	        let path_enc = analyzer.analyze("path", &path_refs);
1568	        let size_enc = analyzer.analyze("content_length", &size_refs);
1569	
1570	        // Print compression summary
1571	        println!("\n=== Apache Access Log Compression Ratios ({n} docs) ===");
1572	        println!(
1573	            "{:<20} {:>10} {:>10} {:>8}",
1574	            "field", "bytes/val", "raw bytes", "ratio"
1575	        );
1576	        println!("{}", "-".repeat(52));
1577	
1578	        let fields: &[(&str, &FieldEncoding, f64)] = &[
1579	            ("status", &status_enc, 3.0),
1580	            ("method", &method_enc, 4.0),
1581	            ("client_ip", &ip_enc, 14.0),
1582	            ("@timestamp", &ts_enc, 25.0),
1583	            ("path", &path_enc, 30.0),
1584	            ("content_length", &size_enc, 6.0),
1585	        ];
1586	
1587	        for (name, enc, raw_bpv) in fields {
1588	            println!(
1589	                "{:<20} {:>10.2} {:>10.1} {:>8.1}x",
1590	                name,
1591	                enc.bytes_per_value(),
1592	                raw_bpv,
1593	                raw_bpv / enc.bytes_per_value().max(0.01)
1594	            );
1595	        }
1596	
1597	        // Validate specific assertions from the spec
1598	        // status: 0.5 bytes vs 3
1599	        assert!(
1600	            status_enc.bytes_per_value() < 1.5,
1601	            "status should use <1.5 bytes/value, got {:.2}",
1602	            status_enc.bytes_per_value()
