1463	/// Discover every WAL directory under `wal_root` and return all replayable
1464	/// entries merge-sorted by `seq_no`.
1465	///
1466	/// Two layouts are supported, matching what `IndexStore` writes:
1467	/// - legacy single-WAL: `*.wal` files directly in `wal_root`
1468	/// - sharded WAL: `wal_root/s{N}/` subdirectories, one WAL stream per
1469	///   ingest shard
1470	///
1471	/// Sorting globally by `seq_no` is required for correctness: a delete of a
1472	/// document can live in a different shard stream than a later re-index of
1473	/// the same id, so per-directory order alone must not be trusted. Corrupt
1474	/// entries are skipped with a warning, matching single-dir replay.
1475	pub fn replay_all_sorted(wal_root: &Path) -> Vec<ReplayEntry> {
1476	    let mut wal_dirs: Vec<PathBuf> = Vec::new();
1477	    // Legacy layout: .wal files directly in the root.
1478	    if fs::read_dir(wal_root)
1479	        .ok()
1480	        .map(|rd| {
1481	            rd.filter_map(|e| e.ok())
1482	                .any(|e| e.path().extension().map(|x| x == "wal").unwrap_or(false))
1483	        })
1484	        .unwrap_or(false)
1485	    {
1486	        wal_dirs.push(wal_root.to_path_buf());
1487	    }
1488	    // Sharded layout: s0, s1, … subdirectories.
1489	    if let Ok(rd) = fs::read_dir(wal_root) {
1490	        for entry in rd.filter_map(|e| e.ok()) {
1491	            let name = entry.file_name();
1492	            let name_str = name.to_string_lossy();
1493	            if name_str.starts_with('s')
1494	                && name_str[1..].parse::<usize>().is_ok()
1495	                && entry.path().is_dir()
1496	            {
1497	                wal_dirs.push(entry.path());
1498	            }
1499	        }
1500	    }
1501	
1502	    let mut all_entries: Vec<ReplayEntry> = Vec::new();
1503	    for dir in &wal_dirs {
1504	        let reader = WalReader::new(dir);
1505	        let iter = match reader.replay() {
1506	            Ok(it) => it,
1507	            Err(e) => {
1508	                warn!(error = %e, ?dir, "failed to open WAL for replay");
1509	                continue;
1510	            }
1511	        };
1512	        for result in iter {
1513	            match result {
1514	                Ok(e) => all_entries.push(e),
1515	                Err(e) => {
1516	                    warn!(error = %e, ?dir, "skipping corrupt WAL entry during replay");
1517	                }
1518	            }
1519	        }
1520	    }
1521	    all_entries.sort_by_key(|e| e.seq_no);
