1543	/// Parse the frame starting at `off`.  Integrity gate is the CRC over
1544	/// seq_no + op + payload; a frame that passes it is genuine (2^-32 for
1545	/// random bytes, further narrowed by the length/op sanity checks used
1546	/// by the resync scan).
1547	fn parse_raw_frame(buf: &[u8], off: usize) -> RawFrame<'_> {
1548	    if off == buf.len() {
1549	        return RawFrame::End;
1550	    }
1551	    if off + 13 > buf.len() {
1552	        return RawFrame::Corrupt; // truncated header
1553	    }
1554	    let entry_len = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
1555	    if entry_len > WAL_MAX_ENTRY_LEN {
1556	        return RawFrame::Corrupt;
1557	    }
1558	    let total = WAL_FRAME_OVERHEAD + entry_len as usize;
1559	    if off + total > buf.len() {
1560	        return RawFrame::Corrupt; // truncated payload/crc
1561	    }
1562	    let seq_no = u64::from_le_bytes(buf[off + 4..off + 12].try_into().unwrap());
1563	    let op_code = buf[off + 12];
1564	    let payload = &buf[off + 13..off + 13 + entry_len as usize];
1565	    let stored_crc = u32::from_le_bytes(
1566	        buf[off + 13 + entry_len as usize..off + total]
1567	            .try_into()
1568	            .unwrap(),
1569	    );
1570	
1571	    let mut hasher = Crc32Hasher::new();
1572	    hasher.update(&buf[off + 4..off + 12]); // seq_no LE bytes
1573	    hasher.update(&[op_code]);
1574	    hasher.update(payload);
1575	    if hasher.finalize() != stored_crc {
1576	        return RawFrame::Corrupt;
1577	    }
1578	    RawFrame::Frame {
1579	        seq_no,
1580	        op_code,
1581	        payload,
1582	        end: off + total,
1583	    }
1584	}
