1586	/// Scan forward from `from` for the next offset that parses as a
1587	/// CRC-valid frame with a KNOWN op code — the boundary-resync primitive.
1588	/// The op-code check (8 valid values of 256) stacks with the CRC to make
1589	/// a false resync on garbage astronomically unlikely.
1590	fn scan_next_valid_frame(buf: &[u8], from: usize) -> Option<usize> {
1591	    let mut c = from;
1592	    while c + WAL_FRAME_OVERHEAD <= buf.len() {
1593	        // Cheap pre-filter before paying a CRC: plausible op byte.
1594	        let op = buf.get(c + 12).copied().unwrap_or(0);
1595	        if WalOpCode::from_u8(op & !OP_COMPRESSED_FLAG).is_some() {
1596	            if let RawFrame::Frame { .. } = parse_raw_frame(buf, c) {
1597	                return Some(c);
1598	            }
1599	        }
1600	        c += 1;
1601	    }
1602	    None
1603	}
