1607	enum WalTailScan {
1608	    /// Every byte parses cleanly: append at `end` (== file length).
1609	    Clean { end: u64 },
1610	    /// Garbage after the last valid frame with NO valid frame beyond it —
1611	    /// the classic crash/ENOSPC tail tear.  Truncate to `last_good_end`.
1612	    TornTail { last_good_end: u64 },
