1619	/// Classify the tail state of a WAL file (see [`WalTailScan`]).
1620	fn scan_wal_tail(path: &Path) -> io::Result<WalTailScan> {
1621	    let buf = fs::read(path)?;
1622	    if buf.len() < WAL_HEADER_LEN as usize || &buf[..4] != WAL_MAGIC {
1623	        // Unreadable header (e.g. crash during file creation) — never
1624	        // append after it.
1625	        return Ok(WalTailScan::MidFileCorruption);
1626	    }
1627	    let mut off = WAL_HEADER_LEN as usize;
1628	    loop {
1629	        match parse_raw_frame(&buf, off) {
1630	            RawFrame::End => return Ok(WalTailScan::Clean { end: off as u64 }),
1631	            RawFrame::Frame { end, .. } => off = end,
1632	            RawFrame::Corrupt => {
1633	                return if scan_next_valid_frame(&buf, off + 1).is_some() {
1634	                    Ok(WalTailScan::MidFileCorruption)
1635	                } else {
1636	                    Ok(WalTailScan::TornTail {
1637	                        last_good_end: off as u64,
1638	                    })
1639	                };
1640	            }
1641	        }
1642	    }
1643	}
