1677	        Ok(b) => b,
1678	        Err(e) => return vec![Err(e.into())],
1679	    };
1680	    if buf.len() < 4 {
1681	        return vec![];
1682	    }
1683	    if &buf[..4] != WAL_MAGIC {
1684	        return vec![Err(StorageError::InvalidMagic {
1685	            expected: WAL_MAGIC,
1686	            actual: buf[..4].to_vec(),
1687	        })];
1688	    }
1689	    if buf.len() < WAL_HEADER_LEN as usize {
1690	        return vec![];
1691	    }
1692	    let generation = u64::from_le_bytes(buf[4..12].try_into().unwrap());
1693	
1694	    let mut results: Vec<Result<ReplayEntry>> = Vec::new();
1695	    let mut off = WAL_HEADER_LEN as usize;
1696	
1697	    loop {
1698	        match parse_raw_frame(&buf, off) {
1699	            RawFrame::End => break,
1700	            RawFrame::Corrupt => {
1701	                match scan_next_valid_frame(&buf, off + 1) {
1702	                    Some(next) => {
1703	                        warn!(
1704	                            generation,
1705	                            offset = off,
1706	                            resync_at = next,
1707	                            "WAL corrupt region mid-file — resynced to next valid frame \
1708	                             boundary (entries in the gap are lost; file retained by prune)"
1709	                        );
1710	                        results.push(Err(StorageError::WalCorrupt(
1711	                            off as u64,
1712	                            format!("gen={generation} corrupt region at {off}, resynced at {next}"),
1713	                        )));
1714	                        off = next;
1715	                    }
1716	                    None => {
1717	                        // Torn tail — everything before it was recovered.
1718	                        results.push(Err(StorageError::WalCorrupt(
1719	                            off as u64,
1720	                            format!("gen={generation} truncated/torn tail"),
1721	                        )));
1722	                        break;
1723	                    }
1724	                }
1725	            }
1726	            RawFrame::Frame {
1727	                seq_no,
1728	                op_code,
1729	                payload,
1730	                end,
1731	            } => {
1732	                let this_offset = off as u64;
1733	                off = end;
1734	
1735	                match decode_frame_payload(op_code, payload, generation, this_offset) {
1736	                    FrameDecode::Entry(entry) => results.push(Ok(ReplayEntry {
1737	                        seq_no,
1738	                        entry,
1739	                        file_offset: this_offset,
1740	                    })),
1741	                    FrameDecode::UnknownOp => continue,
1742	                    FrameDecode::Bad(e) => {
1743	                        results.push(Err(e));
1744	                        continue;
1745	                    }
1746	                }
1747	            }
1748	        }
1749	    }
