1751	    // M5.8 — sort by seq_no so that the M5.8 lock-free WAL writer path
1752	    // (which may land frames out-of-order in the file under high
1753	    // concurrency) still replays in correct seq_no order.  Errors float
1754	    // to the end so they don't disturb the sort key.
1755	    results.sort_by_key(|r| match r {
1756	        Ok(e) => (0u8, e.seq_no),
1757	        Err(_) => (1u8, u64::MAX),
1758	    });
