1831	        WalEntry::Index { .. } => WalOpCode::Index,
1832	        WalEntry::Delete { .. } => WalOpCode::Delete,
1833	        WalEntry::UpdateMapping { .. } => WalOpCode::UpdateMapping,
1834	    };
