1368	    fn stream_crc32_from_reader(mut reader: impl std::io::Read) -> std::io::Result<u32> {
1369	        let mut hasher = crc32fast::Hasher::new();
1370	        let mut buffer = [0u8; 64 * 1024];
1371	        loop {
1372	            let read = reader.read(&mut buffer)?;
1373	            if read == 0 {
1374	                break;
1375	            }
1376	            hasher.update(&buffer[..read]);
1377	        }
1378	        Ok(hasher.finalize())
1379	    }
