140	//
141	// V2 makes acked deletes SEGMENT-DURABLE: reopen applies these pairs
142	// max-seq-wins against the doc entries rebuilt from `.ids`/stored, so a
143	// delete survives restart without its WAL entry — which is what finally
144	// lets WAL maintenance unpin delete-bearing shards (the pre-fix pinning
145	// retained one WAL generation per shard FOREVER after a single plain
146	// delete).  The legacy payload (a bare JSON array of doc_id strings,
147	// written since the 2026-07 delete-durability fix but never read) has no
148	// seq information and is IGNORED by `decode_tombstones_v2` — those
149	// deletes remain protected by WAL pinning exactly as before.
150	
151	/// Encode `(delete_seq_no, doc_id)` pairs as a ZTB2 tombstone section.
152	pub fn encode_tombstones_v2(pairs: &[(u64, &str)]) -> Vec<u8> {
153	    let mut body: Vec<u8> =
154	        Vec::with_capacity(pairs.iter().map(|(_, id)| 8 + 2 + id.len()).sum::<usize>());
155	    for (seq, id) in pairs {
156	        body.extend_from_slice(&seq.to_le_bytes());
157	        body.extend_from_slice(&(id.len() as u16).to_le_bytes());
158	        body.extend_from_slice(id.as_bytes());
159	    }
160	    let compressed = lz4_flex::compress_prepend_size(&body);
161	    let mut out = Vec::with_capacity(8 + compressed.len());
162	    out.extend_from_slice(b"ZTB2");
163	    out.extend_from_slice(&(pairs.len() as u32).to_le_bytes());
164	    out.extend_from_slice(&compressed);
165	    out
166	}
