168	/// Decode a ZTB2 tombstone section.  Returns `None` for the legacy
169	/// id-only JSON payload (no seq info — cannot be applied safely) or any
170	/// malformed input.
171	pub fn decode_tombstones_v2(bytes: &[u8]) -> Option<Vec<(u64, String)>> {
172	    if bytes.len() < 8 || &bytes[..4] != b"ZTB2" {
173	        return None;
174	    }
175	    let count = u32::from_le_bytes(bytes[4..8].try_into().ok()?) as usize;
176	    let body = lz4_flex::decompress_size_prepended(&bytes[8..]).ok()?;
177	    let mut out = Vec::with_capacity(count);
178	    let mut pos = 0usize;
179	    for _ in 0..count {
180	        if pos + 10 > body.len() {
181	            return None;
182	        }
183	        let seq = u64::from_le_bytes(body[pos..pos + 8].try_into().ok()?);
184	        pos += 8;
185	        let id_len = u16::from_le_bytes(body[pos..pos + 2].try_into().ok()?) as usize;
186	        pos += 2;
187	        if pos + id_len > body.len() {
188	            return None;
189	        }
190	        let id = std::str::from_utf8(&body[pos..pos + id_len])
191	            .ok()?
192	            .to_string();
193	        pos += id_len;
194	        out.push((seq, id));
195	    }
196	    Some(out)
197	}
