305	
306	/// Lightweight metadata kept in memory for a segment.
307	///
308	/// ## Upgrade hygiene (RC4 W3 #10)
309	///
310	/// This struct is serialized into the on-disk `snapshot.json` manifest that
311	/// makes flushed segments discoverable on restart. To keep that manifest
312	/// forward/backward compatible across xerj versions, every *descriptive*
313	/// field carries `#[serde(default)]` so that a newer field added in a later
314	/// release does not break an older snapshot open, and an older snapshot
315	/// missing a field written by a newer release still loads (the field takes
316	/// its default). serde already ignores unknown fields, so the reverse
317	/// direction (older binary, newer manifest) works too.
318	///
319	/// The identity/locator fields (`id`, `seg_path`) are deliberately left

540	///
541	/// The OS page cache backs the reads — no heap copies for the common path.
542	/// Section data is validated on first access (CRC32C).
543	pub struct SegmentReader {
544	    mmap: Arc<Mmap>,
545	    header: SegmentHeader,
546	    sections: Vec<SectionEntry>,
547	}
548	
549	impl SegmentReader {
550	    /// Open the `.seg` file at `path` and validate the header + footer.
551	    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
552	        let file = File::open(path.as_ref())?;
553	        let mmap = unsafe { Mmap::map(&file) }?;
554	        let mmap = Arc::new(mmap);
555	        let reader = Self::from_mmap(mmap)?;
556	        // #819: `from_mmap`'s open-time whole-file CRC pass reads every
557	        // on-disk byte of the segment, so a validated open is the faithful
558	        // "bytes read from disk" site. The reader-cache hit path
559	        // (`from_mmap_arc`) reuses the mmap and reads nothing, so it
560	        // deliberately does not record.
561	        if let Some(m) = xerj_common::metrics::global_metrics() {
562	            m.record_bytes_read(reader.mmap.len() as u64);
563	        }
564	        Ok(reader)
565	    }
566	
567	    /// Return the underlying Arc<Mmap>.  Used by the cached
568	    /// `open_segment_arc` path to clone SegmentReaders without
569	    /// reopening the file.
570	    pub fn mmap_arc(&self) -> &Arc<Mmap> {
571	        &self.mmap
572	    }
573	
574	    /// Construct a SegmentReader from an already-validated Arc<Mmap>.
575	    /// Bypasses the full-file CRC check — only used from the
576	    /// `open_segment_arc` cache path where the same mmap has already
577	    /// been validated once at cache insertion time.
578	    pub fn from_mmap_arc(mmap: Arc<Mmap>) -> Result<Self> {
579	        // Re-parse the section table without redoing the total CRC.
580	        // The mmap came from a reader that already validated at open.
581	        let data = &mmap[..];
582	        let footer_start = data.len() - FOOTER_LEN as usize;
583	        let mut footer_cur = std::io::Cursor::new(&data[footer_start..]);
584	        let section_table_offset = footer_cur.read_u64::<LittleEndian>()?;
585	        let _stored_total_crc = footer_cur.read_u32::<LittleEndian>()?;
586	        let header = SegmentHeader::read_from(&data[..HEADER_LEN as usize])?;
587	        let st_start = section_table_offset as usize;
588	        let mut st_cur = std::io::Cursor::new(&data[st_start..]);
589	        let section_count = st_cur.read_u32::<LittleEndian>()? as usize;
590	        let mut sections = Vec::with_capacity(section_count);
591	        for _ in 0..section_count {
592	            sections.push(SectionEntry::read_from(&mut st_cur)?);
593	        }
594	        Ok(Self {
595	            mmap,
596	            header,
597	            sections,
598	        })
599	    }
600	
601	    fn from_mmap(mmap: Arc<Mmap>) -> Result<Self> {
602	        let data = &mmap[..];
603	        if data.len() < (HEADER_LEN + FOOTER_LEN) as usize {
604	            return Err(StorageError::WalCorrupt(0, "segment file too small".into()));
605	        }
606	
607	        // Validate footer magic
608	        let footer_start = data.len() - FOOTER_LEN as usize;
609	        let magic_end_offset = data.len() - 4;
610	        if &data[magic_end_offset..] != SEG_MAGIC_END {
611	            return Err(StorageError::InvalidMagic {
612	                expected: SEG_MAGIC_END,
613	                actual: data[magic_end_offset..].to_vec(),
614	            });
615	        }
616	
617	        // Read footer
618	        let mut footer_cur = std::io::Cursor::new(&data[footer_start..]);
619	        let section_table_offset = footer_cur.read_u64::<LittleEndian>()?;
620	        let stored_total_crc = footer_cur.read_u32::<LittleEndian>()?;
621	
622	        // Verify total CRC (everything except footer)
623	        let mut hasher = Crc32Hasher::new();
624	        hasher.update(&data[..footer_start]);
625	        let computed_crc = hasher.finalize();
626	        if stored_total_crc != computed_crc {
627	            return Err(StorageError::ChecksumMismatch {
628	                expected: stored_total_crc,
629	                actual: computed_crc,
630	            });
631	        }
632	
633	        // Parse header
634	        let header = SegmentHeader::read_from(&data[..HEADER_LEN as usize])?;
635	
636	        // Parse section table
637	        let st_start = section_table_offset as usize;
638	        let mut st_cur = std::io::Cursor::new(&data[st_start..]);
639	        let section_count = st_cur.read_u32::<LittleEndian>()? as usize;
640	        let mut sections = Vec::with_capacity(section_count);
641	        for _ in 0..section_count {
642	            sections.push(SectionEntry::read_from(&mut st_cur)?);
643	        }
644	
645	        Ok(Self {
646	            mmap,
647	            header,
648	            sections,
649	        })
650	    }
651	
652	    /// Return the segment header.
653	    pub fn header(&self) -> &SegmentHeader {
654	        &self.header
655	    }
656	
657	    /// Return the raw bytes of a section, or `None` if that section type is
658	    /// not present in this segment.
659	    ///
660	    /// M5.20 — section CRC is NO LONGER re-validated on every call.
661	    /// The whole-file CRC is validated once at open time (in
662	    /// `from_mmap`); individual section CRCs were verifying the same
663	    /// immutable bytes on every query, which was a significant share
664	    /// of CPU time on concurrent-search benchmarks (197 segments ×
665	    /// ~500 KB stored = ~100 MB of CRC32 per query, 50 ms per query
666	    /// just in checksum work).  If you want strict per-section CRC
667	    /// checking, use `section_checked` below.
668	    pub fn section(&self, kind: SectionType) -> Result<Option<&[u8]>> {
669	        let entry = match self.sections.iter().find(|e| e.section_type == kind) {
670	            Some(e) => e,
671	            None => return Ok(None),
672	        };
673	        let start = entry.offset as usize;
674	        let end = start + entry.length as usize;
675	        Ok(Some(&self.mmap[start..end]))
676	    }
677	
678	    /// Same as `section()` but re-validates the per-section CRC on
679	    /// every call.  Useful for `fsck`-style integrity checks; the
680	    /// fast path uses `section()` which relies on the open-time
681	    /// whole-file CRC.
682	    pub fn section_checked(&self, kind: SectionType) -> Result<Option<&[u8]>> {
683	        let entry = match self.sections.iter().find(|e| e.section_type == kind) {
684	            Some(e) => e,
685	            None => return Ok(None),
686	        };
687	        let start = entry.offset as usize;
688	        let end = start + entry.length as usize;
689	        let slice = &self.mmap[start..end];
690	        let mut hasher = Crc32Hasher::new();
691	        hasher.update(slice);
692	        let crc = hasher.finalize();
693	        if crc != entry.crc32c {
694	            return Err(StorageError::ChecksumMismatch {
695	                expected: entry.crc32c,
696	                actual: crc,
697	            });
698	        }
699	        Ok(Some(slice))
700	    }
701	
702	    /// List all section types present in this segment.
703	    pub fn section_types(&self) -> Vec<SectionType> {
704	        self.sections.iter().map(|e| e.section_type).collect()
705	    }
706	}
