4437	    fn replay_wal(&self, wal_dir: &Path) -> Result<()> {
4438	        // Discover legacy + sharded WAL streams and merge-sort by seq_no
4439	        // (shared with the engine-level FTS memtable rebuild so the two
4440	        // replay passes can never diverge on directory layout).
4441	        let all_entries = crate::wal::replay_all_sorted(wal_dir);
4442	
4443	        let mut count = 0usize;
4444	        for replay_entry in all_entries {
4445	            match replay_entry.entry {
4446	                WalEntry::Index { doc_id, source } => {
4447	                    let seq_no = replay_entry.seq_no;
4448	                    // Replay idempotence (2026-07, S2): if the version map —
4449	                    // rebuilt from segments BEFORE replay — already shows this
4450	                    // doc live in a real segment at seq_no >= this op, the
4451	                    // exact same op (equal seq: the shutdown flush persisted
4452	                    // it) or a newer version is already segment-durable.
4453	                    // Re-materialising it in the memtable created a SECOND
4454	                    // copy of the same (id, seq_no): the strict `doc_seq <
4455	                    // ver.seq_no` stale-copy predicates on the count paths
4456	                    // don't skip an equal-seq segment copy, so counts were
4457	                    // inflated after a SIGTERM restart whose WAL shard was
4458	                    // pinned by an unpersisted delete (batch-6 pinning
4459	                    // correctly preserved the shard, preserving the already-
4460	                    // flushed overwrite entries with it).  Skip the memtable
4461	                    // push and version_map set; the seq counter is still
4462	                    // fetch_max'd below.
4463	                    //
4464	                    // Caveat: legacy segments without a `.ids` sidecar
4465	                    // rebuild version-map seqs by approximation
4466	                    // (`rebuild_version_map_from_segments`); with the seq
4467	                    // counter now seeded from segment metadata on open, any
4468	                    // post-flush update carries a seq strictly greater than
4469	                    // its segment's max_seq_no, so the approximation cannot
4470	                    // shadow a genuinely newer WAL-only version.
4471	                    let already_persisted = match self.version_map.get(&doc_id) {
4472	                        Some(e) => {
4473	                            !e.deleted
4474	                                && e.seq_no >= seq_no
4475	                                && &*e.segment_id != IN_MEMORY_SEGMENT_ID
4476	                        }
4477	                        None => false,
4478	                    };
4479	                    if !already_persisted {
4480	                        self.version_map
4481	                            .set(&doc_id, seq_no, IN_MEMORY_SEGMENT_ID, false);
4482	                        let source_bytes = std::sync::Arc::from(&[][..]);
4483	                        let charge = MemEntry::charge_for(&source, &source_bytes);
4484	                        let shard = self.shard_for(&doc_id);
4485	                        let mut mem = self.memtable_shards[shard].lock().unwrap();
4486	                        mem.push(MemEntry {
4487	                            seq_no,
4488	                            doc_id,
4489	                            source: Some(std::sync::Arc::new(source)),
4490	                            source_bytes,
4491	                            charge,
4492	                        });
4493	                        drop(mem);
4494	                        self.memtable_bytes.fetch_add(charge, Ordering::Relaxed);
4495	                    }
4496	                }
4497	                WalEntry::Delete { doc_id } => {
4498	                    let seq_no = replay_entry.seq_no;
4499	                    // RC4 W2 #14 — seq-aware replay:
4500	                    //
4501	                    // (a) STALE delete (the map — rebuilt from segments,
4502	                    //     including ZTB2 tombstones — already holds a
4503	                    //     strictly newer state for the doc): skip.
4504	                    //     `VersionMap::delete` is seq-blind; pre-fix a
4505	                    //     retained old Delete entry could tombstone a
4506	                    //     NEWER segment-resident version whose own WAL
4507	                    //     entry had already been pruned.
4508	                    // (b) Tombstone already SEGMENT-resident at >= seq
4509	                    //     (rebuilt from a ZTB2 section): the deletion is
4510	                    //     durable without this WAL entry — don't re-apply,
4511	                    //     don't re-pin, don't re-materialise a memtable
4512	                    //     tombstone (which would re-flush it forever).
4513	                    let cur = self.version_map.get(&doc_id);
4514	                    let stale = cur.as_ref().is_some_and(|e| e.seq_no > seq_no);
4515	                    let already_durable = cur.as_ref().is_some_and(|e| {
4516	                        e.deleted && e.seq_no >= seq_no && &*e.segment_id != IN_MEMORY_SEGMENT_ID
4517	                    });
4518	                    if stale || already_durable {
4519	                        let _ = self
4520	                            .seq_counter
4521	                            .fetch_max(replay_entry.seq_no + 1, Ordering::AcqRel);
4522	                        count += 1;
4523	                        continue;
4524	                    }
4525	                    let applied = self
4526	                        .version_map
4527	                        .delete(&doc_id, seq_no, IN_MEMORY_SEGMENT_ID)
4528	                        .unwrap_or(false);
4529	                    // Delete-durability: re-pin the WAL shard whenever the
4530	                    // tombstone applied to a doc that still exists (it may
4531	                    // be live in a segment) — this Delete entry remains the
4532	                    // only durable record of the delete, so maintenance
4533	                    // after THIS restart must keep refusing to prune it;
4534	                    // otherwise the delete survives one restart and the doc
4535	                    // resurrects on the next.  A delete that applied to
4536	                    // nothing (doc already merge-purged from every segment,
4537	                    // or already tombstoned by an earlier pinned entry) is
4538	                    // vacuous and must not pin the shard forever.
4539	                    // Superseded pins (doc re-indexed later in the replay
4540	                    // stream) are cleared by the next
4541	                    // `sweep_pending_deletes` once the newer version is
4542	                    // segment-resident (or once the tombstone itself is
4543	                    // persisted by `persist_pending_tombstones`).
4544	                    if applied {
4545	                        self.pending_deletes
4546	                            .lock()
4547	                            .unwrap()
4548	                            .insert(doc_id.clone(), (seq_no, self.wal_shard_for(&doc_id)));
4549	                    }
4550	                    let shard = self.shard_for(&doc_id);
4551	                    let mut mem = self.memtable_shards[shard].lock().unwrap();
4552	                    mem.push(MemEntry {
4553	                        seq_no,
4554	                        doc_id,
4555	                        source: None,
4556	                        source_bytes: std::sync::Arc::from(&[][..]),
4557	                        charge: TOMBSTONE_CHARGE,
4558	                    });
4559	                    drop(mem);
4560	                    self.memtable_bytes
4561	                        .fetch_add(TOMBSTONE_CHARGE, Ordering::Relaxed);
4562	                }
4563	                WalEntry::UpdateMapping { .. } => {}
4564	            }
4565	            let _ = self
4566	                .seq_counter
4567	                .fetch_max(replay_entry.seq_no + 1, Ordering::AcqRel);
4568	            count += 1;
4569	        }
4570	
4571	        if count > 0 {
4572	            info!(count, "replayed WAL entries");
4573	        }
4574	        Ok(())
4575	    }
