840	/// Parse a ZBS3 wrapper into its `(present_nulls, inner_zbs2_blob)`. The
841	/// caller must have verified `bytes[..4] == STORED_V3_MAGIC`. The returned
842	/// inner slice still carries its own `ZBS2` magic.
843	fn split_stored_v3(bytes: &[u8]) -> Result<StoredV3Parts<'_>> {
844	    let count = bytes
845	        .get(4..8)
846	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v3 present-null count truncated")))
847	        .map(|b| u32::from_le_bytes(b.try_into().unwrap()) as usize)?;
848	    let entries_start = 8usize;
849	    let entries_len = count
850	        .checked_mul(8)
851	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v3 present-null count overflow")))?;
852	    let inner_start = entries_start
853	        .checked_add(entries_len)
854	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v3 present-null section overflow")))?;
855	    let entries = bytes
856	        .get(entries_start..inner_start)
857	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v3 present-null section truncated")))?;
858	    let mut present_nulls = Vec::with_capacity(count);
859	    // `entries` is exactly `count * 8` bytes, so `as_chunks::<8>()` yields
860	    // `count` chunks with an empty remainder (clippy 1.98 `chunks_exact_to_as_chunks`).
861	    for pair in entries.as_chunks::<8>().0 {
862	        let doc = u32::from_le_bytes(pair[0..4].try_into().unwrap());
863	        let col = u32::from_le_bytes(pair[4..8].try_into().unwrap());
864	        present_nulls.push((doc, col));
865	    }
866	    let inner = bytes
867	        .get(inner_start..)
868	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v3 inner blob missing")))?;
869	    if !is_columnar_stored_magic(inner) {
870	        return Err(StorageError::Other(anyhow::anyhow!(
871	            "v3 inner blob is not ZBS2"
872	        )));
873	    }
874	    Ok((present_nulls, inner))
