1250	        as usize;
1251	    const MIN_COLUMN_FRAMING_BYTES: usize =
1252	        std::mem::size_of::<u16>() + std::mem::size_of::<u8>() + std::mem::size_of::<u32>();
1253	    let remaining = body.len().saturating_sub(cur.position() as usize);
1254	    if num_cols > remaining / MIN_COLUMN_FRAMING_BYTES {
1255	        return Err(StorageError::Other(anyhow::anyhow!(
1256	            "v2 num_cols {num_cols} exceeds the remaining directory framing"
1257	        )));
1258	    }
1259	    let mut columns = Vec::new();
1260	    columns.try_reserve_exact(num_cols).map_err(|error| {
1261	        StorageError::Other(anyhow::anyhow!(
1262	            "v2 cannot reserve directory for {num_cols} columns: {error}"
1263	        ))
1264	    })?;
1265	    let mut seen = std::collections::HashSet::new();
1266	    seen.try_reserve(num_cols).map_err(|error| {
1267	        StorageError::Other(anyhow::anyhow!(
1268	            "v2 cannot reserve duplicate-name set for {num_cols} columns: {error}"
1269	        ))
1270	    })?;
1271	    for _ in 0..num_cols {
1272	        let name_len = cur
1273	            .read_u16::<LittleEndian>()
1274	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 name_len: {e}")))?
1275	            as usize;
1276	        let name_start = cur.position() as usize;
1277	        let name_end = name_start
1278	            .checked_add(name_len)
1279	            .filter(|end| *end <= body.len())
1280	            .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v2 truncated name")))?;
1281	        let name = std::str::from_utf8(&body[name_start..name_end])
1282	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 bad name utf8: {e}")))?;
1283	        if !seen.insert(name) {
1284	            return Err(StorageError::Other(anyhow::anyhow!(
1285	                "v2 duplicate column name: {name}"
1286	            )));
1287	        }
1288	        cur.set_position(name_end as u64);
1289	        let codec_id = cur
1290	            .read_u8()
1291	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 codec_id: {e}")))?;
1292	        let codec = ColCodec::from_u8(codec_id)
1293	            .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v2 unknown codec {codec_id}")))?;
1294	        let payload_len = cur
1295	            .read_u32::<LittleEndian>()
1296	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 payload_len: {e}")))?
1297	            as usize;
1298	        let payload_start = cur.position() as usize;
1299	        let payload_end = payload_start
1300	            .checked_add(payload_len)
1301	            .filter(|end| *end <= body.len())
1302	            .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v2 truncated payload")))?;
1303	        columns.push(V2ColumnRef {
1304	            name,
1305	            codec,
1306	            payload: &body[payload_start..payload_end],
1307	        });
1308	        cur.set_position(payload_end as u64);
1309	    }
1310	    if cur.position() as usize != body.len() {
1311	        return Err(StorageError::Other(anyhow::anyhow!(
1312	            "v2 trailing bytes after column payloads"
1313	        )));
1314	    }
1315	    Ok(V2Directory { num_docs, columns })
1316	}
