1318	/// Decode only named columns from a V2 stored section.
1319	///
1320	/// This API does not change `decode_stored` or any engine behavior. It is the
1321	/// storage primitive for consumers that can operate on selected columns
1322	/// without reconstructing every `_source` object.
1323	pub fn decode_stored_v2_projection(
1324	    bytes: &[u8],
1325	    requested: &[&str],
1326	) -> Result<StoredV2ProjectionResult> {
1327	    if !is_columnar_stored_magic(bytes) {
1328	        return Ok(StoredV2ProjectionResult::NotV2);
1329	    }
1330	    let directory = parse_v2_directory(&bytes[4..])?;
1331	    let requested: std::collections::HashSet<&str> = requested.iter().copied().collect();
1332	    let mut decoded = vec![None; directory.columns.len()];
1333	    let mut visiting = vec![false; directory.columns.len()];
1334	    let mut columns = HashMap::with_capacity(requested.len());
1335	    for index in 0..directory.columns.len() {
1336	        let column = &directory.columns[index];
1337	        if requested.contains(column.name) {
1338	            let values =
1339	                decode_projected_column(index, &directory, &mut decoded, &mut visiting, 0)?.clone();
1340	            columns.insert(column.name.to_string(), values);
1341	        }
1342	    }
1343	    Ok(StoredV2ProjectionResult::Projected(StoredV2Projection {
1344	        num_docs: directory.num_docs,
1345	        columns,
1346	    }))
1347	}
