1349	fn decode_cross_dep_body(payload: &[u8], num_docs: usize) -> Result<Vec<u8>> {
1350	    if payload.is_empty() {
1351	        return Err(StorageError::Other(anyhow::anyhow!("cross_dep empty")));
1352	    }
1353	    // A source dictionary cannot contain more entries than source rows.
1354	    // Each mode costs 8 bytes and each row contributes at most one
1355	    // (u32-delta, i64-zigzag) exception of at most 15 bytes.
1356	    let max_body = num_docs
1357	        .checked_mul(23)
1358	        .and_then(|row_bytes| 12usize.checked_add(row_bytes))
1359	        .ok_or_else(|| StorageError::Other(anyhow::anyhow!("cross_dep size overflow")))?;
1360	    let body = if payload[0] == 1 {
1361	        if zstd_frame_content_size(&payload[1..], "cross_dep")?
1362	            .is_some_and(|size| size > max_body as u64)
1363	        {
1364	            return Err(StorageError::Other(anyhow::anyhow!(
1365	                "cross_dep frame exceeds maximum decoded size"
1366	            )));
1367	        }
1368	        let decoder = zstd::stream::read::Decoder::new(&payload[1..])
1369	            .map_err(|e| StorageError::Other(anyhow::anyhow!("cross_dep zstd decode: {e}")))?;
1370	        let mut bounded = decoder.take(max_body as u64 + 1);
1371	        let mut body = Vec::new();
1372	        bounded
1373	            .read_to_end(&mut body)
1374	            .map_err(|e| StorageError::Other(anyhow::anyhow!("cross_dep zstd decode: {e}")))?;
1375	        if body.len() > max_body {
1376	            return Err(StorageError::Other(anyhow::anyhow!(
1377	                "cross_dep decoded body exceeds limit"
1378	            )));
1379	        }
1380	        body
1381	    } else if payload[0] == 0 {
1382	        if payload.len() - 1 > max_body {
1383	            return Err(StorageError::Other(anyhow::anyhow!(
1384	                "cross_dep raw body exceeds limit"
1385	            )));
1386	        }
1387	        payload[1..].to_vec()
1388	    } else {
1389	        Err(StorageError::Other(anyhow::anyhow!(
1390	            "cross_dep invalid compression flag {}",
1391	            payload[0]
1392	        )))?
1393	    };
1394	    Ok(body)
1395	}
