1413	fn decode_projected_column<'a>(
1414	    index: usize,
1415	    directory: &'a V2Directory<'a>,
1416	    decoded: &'a mut [Option<Vec<serde_json::Value>>],
1417	    visiting: &mut [bool],
1418	    depth: usize,
1419	) -> Result<&'a Vec<serde_json::Value>> {
1420	    const MAX_CROSS_DEP_DEPTH: usize = 256;
1421	    if depth > MAX_CROSS_DEP_DEPTH {
1422	        return Err(StorageError::Other(anyhow::anyhow!(
1423	            "cross_dep dependency depth exceeds {MAX_CROSS_DEP_DEPTH}"
1424	        )));
1425	    }
1426	    if decoded.get(index).and_then(Option::as_ref).is_some() {
1427	        return Ok(decoded[index].as_ref().unwrap());
1428	    }
1429	    if index >= directory.columns.len() || index >= visiting.len() {
1430	        return Err(StorageError::Other(anyhow::anyhow!(
1431	            "cross_dep source index {index} out of range"
1432	        )));
1433	    }
1434	    if visiting[index] {
1435	        return Err(StorageError::Other(anyhow::anyhow!(
1436	            "cross_dep dependency cycle at column {index}"
1437	        )));
1438	    }
1439	    visiting[index] = true;
1440	    let column = &directory.columns[index];
1441	    let values = match column.codec {
1442	        ColCodec::RawJson => decode_raw_json(column.payload)?,
1443	        ColCodec::Lz4Json => decode_lz4_json(column.payload)?,

1443	        ColCodec::Lz4Json => decode_lz4_json(column.payload)?,
1444	        ColCodec::Constant => decode_constant(column.payload, directory.num_docs)?,
1445	        ColCodec::DictBitpack => decode_dict_bitpack(column.payload, directory.num_docs)?,
1446	        ColCodec::TypedInt => decode_typed_int(column.payload, directory.num_docs)?,
1447	        // COPY_OF references an earlier column; the recursion (guarded by
1448	        // `visiting`/`depth` exactly like CrossDep's) materialises it and
1449	        // the clone IS this column's value vector.
1450	        ColCodec::CopyOf => {
1451	            let src_ix = copy_of_source_index(column.payload)?;
1452	            decode_projected_column(src_ix, directory, decoded, visiting, depth + 1)?.clone()
1453	        }
1454	        ColCodec::CrossDep => {
1455	            let source_index = cross_dep_source_index(column.payload, directory.num_docs)?;
1456	            let source =
1457	                decode_projected_column(source_index, directory, decoded, visiting, depth + 1)?
1458	                    .clone();
1459	            let mut dependencies = vec![Vec::new(); directory.columns.len()];
1460	            dependencies[source_index] = source;
1461	            decode_cross_dep(
1462	                column.payload,
1463	                directory.num_docs,
1464	                &dependencies,
1465	                &HashMap::new(),
1466	            )?
1467	            .ok_or_else(|| {
1468	                StorageError::Other(anyhow::anyhow!(
1469	                    "cross_dep source column {source_index} was not resolved"
1470	                ))
1471	            })?
1472	        }
1473	    };
1474	    visiting[index] = false;
1475	    if values.len() != directory.num_docs {
1476	        return Err(StorageError::Other(anyhow::anyhow!(
1477	            "v2 column {} row count {} != header {}",
1478	            column.name,
1479	            values.len(),
1480	            directory.num_docs
1481	        )));
1482	    }
1483	    decoded[index] = Some(values);
1484	    Ok(decoded[index].as_ref().unwrap())
1485	}
