1487	fn finite_f32_vector(values: Vec<f64>) -> Option<Vec<f32>> {
1488	    let mut out = Vec::with_capacity(values.len());
1489	    for value in values {
1490	        let value = value as f32;
1491	        if !value.is_finite() {
1492	            return None;
1493	        }
1494	        out.push(value);
1495	    }
1496	    Some(out)
1497	}
