1499	struct TypedVectorRowsVisitor<'a> {
1500	    expected_rows: usize,
1501	    column_index: usize,
1502	    checkpoint: &'a mut dyn FnMut(StoredDecodeCheckpoint) -> std::ops::ControlFlow<()>,
1503	    cancelled: &'a std::cell::Cell<bool>,
1504	}
1505	
1506	impl<'de> serde::de::Visitor<'de> for TypedVectorRowsVisitor<'_> {
1507	    type Value = Option<StoredVectorRows>;
1508	
1509	    fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
1510	        f.write_str("a vector column JSON array")
1511	    }
1512	
1513	    fn visit_seq<A>(self, mut seq: A) -> std::result::Result<Self::Value, A::Error>
1514	    where
1515	        A: serde::de::SeqAccess<'de>,
1516	    {
1517	        let mut out = Vec::new();
1518	        out.try_reserve_exact(self.expected_rows)
1519	            .map_err(serde::de::Error::custom)?;
1520	        let mut supported = true;
1521	        for row in 0..self.expected_rows {
1522	            let Some(value) = seq.next_element::<serde_json::Value>()? else {
1523	                return Err(serde::de::Error::custom("vector column ended early"));
1524	            };
1525	            let typed = match value {
1526	                serde_json::Value::Null => None,
1527	                serde_json::Value::Array(values) => {
1528	                    let values = values
1529	                        .into_iter()
1530	                        .map(|value| value.as_f64())
1531	                        .collect::<Option<Vec<_>>>()
1532	                        .and_then(finite_f32_vector);
1533	                    let Some(values) = values else {
1534	                        supported = false;
1535	                        out.push(None);
1536	                        if checkpoint_decoded_row(
1537	                            row,
1538	                            self.column_index,
1539	                            self.checkpoint,
1540	                            self.cancelled,
1541	                        ) {
1542	                            return Err(serde::de::Error::custom("stored decode cancelled"));
1543	                        }
1544	                        continue;
1545	                    };
1546	                    Some(values)
1547	                }
1548	                _ => {
1549	                    supported = false;
1550	                    None
1551	                }
1552	            };
1553	            out.push(typed);
1554	            if checkpoint_decoded_row(row, self.column_index, self.checkpoint, self.cancelled) {
1555	                return Err(serde::de::Error::custom("stored decode cancelled"));
1556	            }
1557	        }
1558	        if seq.next_element::<serde::de::IgnoredAny>()?.is_some() {
1559	            return Err(serde::de::Error::custom("vector column has extra rows"));
1560	        }
1561	        Ok(supported.then_some(out))
1562	    }
1563	}
