1565	fn checkpoint_decoded_row(
1566	    zero_based_row: usize,
1567	    column_index: usize,
1568	    checkpoint: &mut dyn FnMut(StoredDecodeCheckpoint) -> std::ops::ControlFlow<()>,
1569	    cancelled: &std::cell::Cell<bool>,
1570	) -> bool {
1571	    let processed = zero_based_row + 1;
1572	    if processed.is_multiple_of(STORED_DECODE_CHECK_INTERVAL)
1573	        && checkpoint(StoredDecodeCheckpoint {
1574	            phase: StoredDecodePhase::Rows,
1575	            column_index,
1576	            rows_processed: processed,
1577	        })
1578	        .is_break()
1579	    {
1580	        cancelled.set(true);
1581	        return true;
1582	    }
1583	    false
1584	}
