1586	fn repeat_constant_rows_controlled<T: Clone>(
1587	    row: T,
1588	    num_docs: usize,
1589	    column_index: usize,
1590	    checkpoint: &mut dyn FnMut(StoredDecodeCheckpoint) -> std::ops::ControlFlow<()>,
1591	) -> Result<std::result::Result<Vec<T>, ()>> {
1592	    let mut out = Vec::new();
1593	    out.try_reserve_exact(num_docs).map_err(|error| {
1594	        StorageError::Other(anyhow::anyhow!(
1595	            "cannot reserve {num_docs} constant stored rows: {error}"
1596	        ))
1597	    })?;
1598	    for zero_based_row in 0..num_docs {
1599	        out.push(row.clone());
1600	        let processed = zero_based_row + 1;
1601	        if processed.is_multiple_of(STORED_DECODE_CHECK_INTERVAL)
1602	            && checkpoint(StoredDecodeCheckpoint {
1603	                phase: StoredDecodePhase::Rows,
1604	                column_index,
1605	                rows_processed: processed,
1606	            })
1607	            .is_break()
1608	        {
1609	            return Ok(Err(()));
1610	        }
1611	    }
1612	    Ok(Ok(out))
1613	}
