1615	fn decode_typed_vector_rows_controlled(
1616	    column: &V2ColumnRef<'_>,
1617	    num_docs: usize,
1618	    column_index: usize,
1619	    checkpoint: &mut dyn FnMut(StoredDecodeCheckpoint) -> std::ops::ControlFlow<()>,
1620	) -> Result<std::result::Result<Option<StoredVectorRows>, ()>> {
1621	    if column.codec == ColCodec::Constant {
1622	        let row = match serde_json::from_slice::<serde_json::Value>(column.payload)
1623	            .map_err(|error| StorageError::Other(anyhow::anyhow!("constant decode: {error}")))?
1624	        {
1625	            serde_json::Value::Null => None,
1626	            serde_json::Value::Array(values) => {
1627	                let Some(values) = values
1628	                    .into_iter()
1629	                    .map(|value| value.as_f64())
1630	                    .collect::<Option<Vec<_>>>()
1631	                    .and_then(finite_f32_vector)
1632	                else {
1633	                    return Ok(Ok(None));
1634	                };
1635	                Some(values)
1636	            }
1637	            _ => return Ok(Ok(None)),
1638	        };
1639	        return repeat_constant_rows_controlled(row, num_docs, column_index, checkpoint)
1640	            .map(|result| result.map(Some));
1641	    }
1642	    match column.codec {
1643	        ColCodec::RawJson => {
1644	            let frame = decode_raw_payload(column.payload)?;
1645	            let decoder = zstd::stream::read::Decoder::new(frame).map_err(|error| {
1646	                StorageError::Other(anyhow::anyhow!("raw zstd decode: {error}"))
1647	            })?;
1648	            parse_typed_vector_reader(decoder, num_docs, column_index, checkpoint)
1649	        }
1650	        ColCodec::Lz4Json => {
1651	            let raw = lz4_flex::decompress_size_prepended(column.payload)
1652	                .map_err(|error| StorageError::Other(anyhow::anyhow!("lz4 decode: {error}")))?;
1653	            parse_typed_vector_reader(raw.as_slice(), num_docs, column_index, checkpoint)
1654	        }
1655	        _ => Ok(Ok(None)),
1656	    }
1657	}
