1659	fn parse_typed_vector_reader<R: std::io::Read>(
1660	    reader: R,
1661	    num_docs: usize,
1662	    column_index: usize,
1663	    checkpoint: &mut dyn FnMut(StoredDecodeCheckpoint) -> std::ops::ControlFlow<()>,
1664	) -> Result<std::result::Result<Option<StoredVectorRows>, ()>> {
1665	    use serde::de::Deserializer as _;
1666	    let cancelled = std::cell::Cell::new(false);
1667	    let mut deserializer = serde_json::Deserializer::from_reader(reader);
1668	    let value = match deserializer.deserialize_seq(TypedVectorRowsVisitor {
1669	        expected_rows: num_docs,
1670	        column_index,
1671	        checkpoint,
1672	        cancelled: &cancelled,
1673	    }) {
1674	        Ok(value) => value,
1675	        Err(_) if cancelled.get() => return Ok(Err(())),
1676	        Err(error) => {
1677	            return Err(StorageError::Other(anyhow::anyhow!(
1678	                "vector json decode: {error}"
1679	            )));
1680	        }
1681	    };
1682	    if value.is_some() {
1683	        deserializer
1684	            .end()
1685	            .map_err(|error| StorageError::Other(anyhow::anyhow!("vector json decode: {error}")))?;
1686	    }
1687	    Ok(Ok(value))
1688	}
