1996	fn decode_stored_v2(body: &[u8], present_nulls: &[(u32, u32)]) -> Result<Vec<u8>> {
1997	    // Positions that were a *present* explicit `_source` null (issue #415).
1998	    // Empty for plain ZBS2 segments; populated by `split_stored_v3` for ZBS3.
1999	    let present_null_set: std::collections::HashSet<(u32, u32)> =
2000	        present_nulls.iter().copied().collect();
2001	    let mut cur = Cursor::new(body);
2002	    let num_docs = cur
2003	        .read_u32::<LittleEndian>()
2004	        .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 num_docs: {e}")))?
2005	        as usize;
2006	    let num_cols = cur
2007	        .read_u32::<LittleEndian>()
2008	        .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 num_cols: {e}")))?
2009	        as usize;
2010	
2011	    // First pass: decode each column into Vec<Value>.  Store the name
2012	    // alongside so we can re-assemble the docs.
2013	    let mut col_names: Vec<String> = Vec::with_capacity(num_cols);
2014	    let mut col_data: Vec<Vec<serde_json::Value>> = Vec::with_capacity(num_cols);
2015	
2016	    for _ in 0..num_cols {
2017	        let name_len = cur
2018	            .read_u16::<LittleEndian>()
2019	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 name_len: {e}")))?
2020	            as usize;
2021	        let pos = cur.position() as usize;
2022	        if body.len() < pos + name_len {
2023	            return Err(StorageError::Other(anyhow::anyhow!("v2 truncated name")));
2024	        }
2025	        let name = std::str::from_utf8(&body[pos..pos + name_len])
2026	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 bad name utf8: {e}")))?
2027	            .to_string();
2028	        cur.set_position((pos + name_len) as u64);
2029	
2030	        let codec_id = cur
2031	            .read_u8()
2032	            .map_err(|e| StorageError::Other(anyhow::anyhow!("v2 codec_id: {e}")))?;
2033	        let codec = ColCodec::from_u8(codec_id)
2034	            .ok_or_else(|| StorageError::Other(anyhow::anyhow!("v2 unknown codec {}", codec_id)))?;
