2717	            .read_u8()
2718	            .map_err(|e| StorageError::Other(anyhow::anyhow!("typed_int varint: {e}")))?;
2719	        result |= ((byte & 0x7F) as u64) << shift;
2720	        if byte & 0x80 != 0 {
