401	        let (mut cur, is_new) = if payload.len() >= 4 && &payload[..4] == b"ZNV1" {
402	            (Cursor::new(&payload[4..]), true)
403	        } else {
404	            (Cursor::new(payload), false)
405	        };
406	
407	        let doc_count = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
408	        let bitmap_len = cur.read_u32::<LittleEndian>().map_err(io_to_storage)? as usize;
409	        let mut bitmap_bytes = vec![0u8; bitmap_len];
410	        cur.read_exact(&mut bitmap_bytes).map_err(io_to_storage)?;
411	        let null_bitmap = RoaringBitmap::deserialize_from(&bitmap_bytes[..])
