418	        // Build the sorted-by-value index in RAM.  Legacy format stored
419	        // it on disk; new format always rebuilds.  For both paths we use
420	        // the single canonical `build_sorted_index` so `range_doc_ids`
421	        // semantics are identical.
422	        let sorted = if is_new {
423	            build_sorted_index(&data, &null_bitmap)
