432	                        let d = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
433	                        s.push((v, d));
434	                    }
435	                    s
436	                }
437	                Err(_) => build_sorted_index(&data, &null_bitmap),
438	            }
439	        };
440	        let (live_count, live_sum, live_min, live_max) = compute_stats(&sorted);
441	
442	        Ok(Self {
443	            doc_count,
444	            null_bitmap,
445	            data,
446	            sorted,
447	            live_count,
448	            live_sum,
449	            live_min,
450	            live_max,
451	        })
