454	    /// ZNV2 reader — the layout mirror of [`encode`](Self::encode).
455	    fn decode_znv2(payload: &[u8]) -> Result<Self> {
456	        let mut cur = Cursor::new(&payload[4..]);
457	        let doc_count = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
458	        let bitmap_len = cur.read_u32::<LittleEndian>().map_err(io_to_storage)? as usize;
459	        let mut bitmap_bytes = vec![0u8; bitmap_len];
460	        cur.read_exact(&mut bitmap_bytes).map_err(io_to_storage)?;
461	        let null_bitmap = RoaringBitmap::deserialize_from(&bitmap_bytes[..])
462	            .map_err(|e| StorageError::Other(anyhow::anyhow!("dv numeric bitmap: {e}")))?;
463	        let u_min = cur.read_u64::<LittleEndian>().map_err(io_to_storage)?;
464	        let gcd = cur.read_u64::<LittleEndian>().map_err(io_to_storage)?;
465	
466	        let mut data = Vec::with_capacity(doc_count as usize);
467	        let mut lanes = [0u32; ZNV2_BLOCK];
468	        let mut packed = Vec::new();
469	        while (data.len() as u32) < doc_count {
470	            let width = cur.read_u8().map_err(io_to_storage)?;
471	            let q_min = read_u64_varint(&mut cur)?;
472	            let base = data.len();
473	            let end = (base + ZNV2_BLOCK).min(doc_count as usize);
474	            match width {
475	                0 => {
476	                    // Constant block: every live value is the same
477	                    // quotient, including the all-null block (q_min 0 —
478	                    // the zeroing pass below restores the null contract).
479	                    let v = znv2_unflip(u_min.wrapping_add(gcd.wrapping_mul(q_min)));
480	                    for _ in base..end {
481	                        data.push(v);
482	                    }
483	                }
484	                ZNV2_WIDE => {
485	                    for _ in 0..ZNV2_BLOCK {
486	                        let r = cur.read_u64::<LittleEndian>().map_err(io_to_storage)?;
487	                        if data.len() < end {
488	                            data.push(znv2_unflip(
489	                                u_min.wrapping_add(gcd.wrapping_mul(q_min.wrapping_add(r))),
490	                            ));
491	                        }
492	                    }
493	                }
494	                w => {
495	                    if w > 32 {
496	                        return Err(StorageError::Other(anyhow::anyhow!(
497	                            "znv2 invalid block width {w}"
498	                        )));
499	                    }
500	                    let nbytes = ZNV2_BLOCK * w as usize / 8;
501	                    packed.clear();
502	                    packed.resize(nbytes, 0);
503	                    cur.read_exact(&mut packed).map_err(io_to_storage)?;
504	                    use bitpacking::BitPacker;
505	                    bitpacking::BitPacker4x::new().decompress(&packed, &mut lanes, w);
506	                    for &lane in lanes.iter().take(end - base) {
507	                        let q = q_min.wrapping_add(u64::from(lane));
508	                        data.push(znv2_unflip(u_min.wrapping_add(gcd.wrapping_mul(q))));
509	                    }
510	                }
511	            }
512	        }
513	        // Null slots: `from_iter` stores 0 there — restore that contract
514	        // so the decoded array is indistinguishable from a built one.
515	        for doc_id in &null_bitmap {
516	            data[doc_id as usize] = 0;
517	        }
518	
519	        let sorted = build_sorted_index(&data, &null_bitmap);
520	        let (live_count, live_sum, live_min, live_max) = compute_stats(&sorted);
521	        Ok(Self {
522	            doc_count,
523	            null_bitmap,
524	            data,
525	            sorted,
526	            live_count,
527	            live_sum,
528	            live_min,
529	            live_max,
530	        })
531	    }
532	}
