788	    pub fn decode(payload: &[u8]) -> Result<Self> {
789	        let mut cur = Cursor::new(payload);
790	        let doc_count = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
791	        let num_terms = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
792	        let ord_width = cur.read_u8().map_err(io_to_storage)?;
793	        let bitmap_len = cur.read_u32::<LittleEndian>().map_err(io_to_storage)? as usize;
794	        let mut bitmap_bytes = vec![0u8; bitmap_len];
795	        cur.read_exact(&mut bitmap_bytes).map_err(io_to_storage)?;
796	        let null_bitmap = RoaringBitmap::deserialize_from(&bitmap_bytes[..])
797	            .map_err(|e| StorageError::Other(anyhow::anyhow!("dv kw bitmap: {e}")))?;
798	        let fst_len = cur.read_u32::<LittleEndian>().map_err(io_to_storage)? as usize;
799	        let mut fst_bytes = vec![0u8; fst_len];
800	        cur.read_exact(&mut fst_bytes).map_err(io_to_storage)?;
801	
802	        // Recover the sorted terms list by walking the FST in lex order.
803	        let map = FstMap::new(&fst_bytes[..])
804	            .map_err(|e| StorageError::Other(anyhow::anyhow!("dv kw fst parse: {e}")))?;
805	        let mut terms_vec: Vec<(u32, String)> = Vec::with_capacity(num_terms as usize);
806	        {
807	            use fst::Streamer;
808	            let mut stream = map.stream();
809	            while let Some((k, v)) = stream.next() {
810	                if let Ok(s) = std::str::from_utf8(k) {
811	                    terms_vec.push((v as u32, s.to_string()));
812	                }
813	            }
814	        }
815	        terms_vec.sort_by_key(|(ord, _)| *ord);
816	        let terms: Vec<String> = terms_vec.into_iter().map(|(_, s)| s).collect();
817	
818	        let mut ords = Vec::with_capacity(doc_count as usize);
819	        for _ in 0..doc_count {
820	            let ord = match ord_width {
821	                1 => cur.read_u8().map_err(io_to_storage)? as u32,
822	                2 => cur.read_u16::<LittleEndian>().map_err(io_to_storage)? as u32,
823	                4 => cur.read_u32::<LittleEndian>().map_err(io_to_storage)?,
824	                _ => return Err(StorageError::Other(anyhow::anyhow!("bad ord_width"))),
825	            };
826	            ords.push(ord);
827	        }
828	
829	        // Rebuild the ord → doc count histogram for fast `doc_freq`
830	        // lookups.  This is not serialised — each segment pays O(doc_count)
831	        // once at decode time and benefits every term query afterwards.
832	        let mut per_ord_count: Vec<u32> = vec![0; terms.len()];
833	        for (i, &ord) in ords.iter().enumerate() {
834	            if !null_bitmap.contains(i as u32) && (ord as usize) < per_ord_count.len() {
835	                per_ord_count[ord as usize] += 1;
836	            }
837	        }
838	
839	        Ok(Self {
840	            doc_count,
841	            terms,
842	            fst_bytes,
843	            null_bitmap,
844	            ords,
845	            per_ord_count,
846	        })
847	    }
848	}
