865	    /// Conservative deterministic estimate of heap allocations retained by
866	    /// this decoded column. This is capacity accounting, not allocator/RSS
867	    /// identity. The inline `Column` enum itself is owned by the caller's
868	    /// map and is intentionally not counted here.
869	    pub fn estimated_retained_bytes(&self) -> u64 {
870	        match self {
871	            Column::Numeric(column) => capacity_bytes::<i64>(column.data.capacity())
872	                .saturating_add(capacity_bytes::<(i64, u32)>(column.sorted.capacity()))
873	                .saturating_add(roaring_retained_bytes(&column.null_bitmap)),
874	            Column::Keyword(column) => {
875	                let term_storage = capacity_bytes::<String>(column.terms.capacity())
876	                    .saturating_add(column.terms.iter().fold(0_u64, |total, term| {
877	                        total.saturating_add(usize_to_u64(term.capacity()))
878	                    }));
879	                term_storage
880	                    .saturating_add(usize_to_u64(column.fst_bytes.capacity()))
881	                    .saturating_add(capacity_bytes::<u32>(column.ords.capacity()))
882	                    .saturating_add(capacity_bytes::<u32>(column.per_ord_count.capacity()))
883	                    .saturating_add(roaring_retained_bytes(&column.null_bitmap))
884	            }
885	        }
886	    }
887	}
