893	fn capacity_bytes<T>(capacity: usize) -> u64 {
894	    usize_to_u64(capacity).saturating_mul(usize_to_u64(std::mem::size_of::<T>()))
895	}
896	
897	fn roaring_retained_bytes(bitmap: &RoaringBitmap) -> u64 {
898	    let statistics = bitmap.statistics();
899	    statistics
900	        .n_bytes_array_containers
901	        .saturating_add(statistics.n_bytes_bitset_containers)
902	        .saturating_add(statistics.n_bytes_run_containers)
903	        // roaring 0.10 does not expose the container Vec capacity. One
904	        // conservative three-word allowance per live container covers the
905	        // key/store slot without pretending serialized size is heap size.
906	        .saturating_add(
907	            u64::from(statistics.n_containers)
908	                .saturating_mul(usize_to_u64(3 * std::mem::size_of::<usize>())),
909	        )
910	}
