912	/// Encode a `field → Column` map into the binary `Columns` section payload.
913	/// Header flag bit on the column kind byte marking a zstd-compressed
914	/// payload (vs the legacy LZ4 path).  The other 7 bits remain the
915	/// numeric/keyword kind discriminator so old readers still see a valid
916	/// kind value — they just fail the magic / length check on the outer
917	/// envelope and fall back to the LZ4 path.
918	const KIND_FLAG_ZSTD: u8 = 0x80;
919	const KIND_MASK: u8 = 0x7F;
920	
921	/// Zstd level the flush path encodes `.dv` columns at. Pinned for the reason
922	/// on `stored_codec::STORED_ZSTD_LEVEL`: flush is the back-pressure-critical
923	/// bound on sustained ingest, and this used to be one of three stacked
924	/// level-19 encoders in a single flush.
925	pub const DV_ZSTD_LEVEL: i32 = 3;
926	
927	/// Encode at [`DV_ZSTD_LEVEL`]; merge calls [`encode_columns_at_level`] to
928	/// honour `compression.level` (#318).
929	pub fn encode_columns(columns: &BTreeMap<String, Column>) -> Vec<u8> {
930	    encode_columns_at_level(columns, DV_ZSTD_LEVEL)
931	}
932	
933	/// [`encode_columns`] at a caller-chosen zstd effort level.
934	///
935	/// Level is a write-side choice only: the reader dispatches on the
936	/// `KIND_FLAG_ZSTD` bit and zstd decode is level-independent, so `.dv` files
937	/// written at different levels coexist in one index with no format change.
938	pub fn encode_columns_at_level(columns: &BTreeMap<String, Column>, level: i32) -> Vec<u8> {
939	    let mut out = Vec::new();
940	    out.write_u32::<LittleEndian>(MAGIC).unwrap();
941	    out.write_u32::<LittleEndian>(columns.len() as u32).unwrap();
942	    for (name, col) in columns {
943	        let kind = match col {
944	            Column::Numeric(_) => KIND_NUMERIC,
945	            Column::Keyword(_) => KIND_KEYWORD,
946	        };
947	        // `level` is DV_ZSTD_LEVEL (3) on flush — fast encode
948	        // (~250 MB/s/core), reverted from level 19 because the flush path
949	        // needs to keep up with sustained ingest (1 M+ docs/s) and the
950	        // level-19 pass collapsed throughput by 70-100× under continuous
951	        // load.  See
952	        // `engine/reports/2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`.
953	        // Merge passes the operator's `compression.level` instead, which is
954	        // off the ingest critical path.
955	        // Legacy LZ4-framed column payloads are still auto-detected by
956	        // the reader via the high bit on the kind byte; level-19-encoded
957	        // segments from older builds remain readable (zstd decompress is
958	        // level-independent).
959	        let compress = |payload: &[u8]| -> Vec<u8> {
960	            zstd::encode_all(payload, level).unwrap_or_else(|_| {
961	                // Fallback: a level-1 pass, else the raw payload.
962	                // Extremely unlikely — `encode_all` only errors on OOM.
963	                zstd::encode_all(payload, 1).unwrap_or_else(|_| payload.to_vec())
964	            })
965	        };
966	        let zstd_payload = match col {
967	            // Numeric columns are the one place a transform can LOSE to
968	            // the outer zstd pass: a periodic column (the size harness
969	            // cycles its 4k-event corpus) is near-nothing after zstd raw,
970	            // while FOR+GCD lanes destroy the byte-aligned repetition the
971	            // matcher was exploiting — and f64-bit-pattern columns whose
972	            // block spread exceeds 32 bits store raw lanes anyway. So
973	            // encode both candidates and keep whichever is smaller AFTER
974	            // compression (the Parquet rule: pick the smallest encoding,
975	            // plain fallback included). The winner's compressed bytes go
976	            // straight into the frame, so the only extra cost is one
977	            // encode + one zstd pass per numeric column. Measured on the
978	            // 100k harness corpus before this guard: bitpack-always was
979	            // 2.0× the `.dv` size of raw.
980	            Column::Numeric(n) => {
981	                let znv2 = compress(&n.encode());
982	                let znv1 = compress(&n.encode_znv1());
983	                if znv2.len() <= znv1.len() {
984	                    znv2
985	                } else {
986	                    znv1
