1001	pub fn decode_columns(bytes: &[u8]) -> Result<BTreeMap<String, Column>> {
1002	    let mut cur = Cursor::new(bytes);
1003	    let magic = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
1004	    if magic != MAGIC {
1005	        return Err(StorageError::Other(anyhow::anyhow!(
1006	            "doc-values magic mismatch: {:#x}",
1007	            magic
1008	        )));
1009	    }
1010	    let num_columns = cur.read_u32::<LittleEndian>().map_err(io_to_storage)?;
1011	    let mut out = BTreeMap::new();
1012	    for _ in 0..num_columns {
1013	        let kind_byte = cur.read_u8().map_err(io_to_storage)?;
1014	        let is_zstd = (kind_byte & KIND_FLAG_ZSTD) != 0;
1015	        let kind = kind_byte & KIND_MASK;
1016	        let name_len = cur.read_u32::<LittleEndian>().map_err(io_to_storage)? as usize;
1017	        let mut name_bytes = vec![0u8; name_len];
1018	        cur.read_exact(&mut name_bytes).map_err(io_to_storage)?;
1019	        let name = String::from_utf8(name_bytes)
1020	            .map_err(|e| StorageError::Other(anyhow::anyhow!("dv field name utf8: {e}")))?;
1021	        let payload_len = cur.read_u64::<LittleEndian>().map_err(io_to_storage)? as usize;
1022	        let mut compressed = vec![0u8; payload_len];
1023	        cur.read_exact(&mut compressed).map_err(io_to_storage)?;
1024	        let payload = if is_zstd {
1025	            zstd::decode_all(&compressed[..])
1026	                .map_err(|e| StorageError::Other(anyhow::anyhow!("dv zstd decompress: {e}")))?
1027	        } else {
1028	            lz4_flex::decompress_size_prepended(&compressed)
1029	                .map_err(|e| StorageError::Other(anyhow::anyhow!("dv lz4 decompress: {e}")))?
1030	        };
1031	        let column = match kind {
1032	            KIND_NUMERIC => Column::Numeric(NumericColumn::decode(&payload)?),
1033	            KIND_KEYWORD => Column::Keyword(KeywordColumn::decode(&payload)?),
1034	            _ => {
1035	                return Err(StorageError::Other(anyhow::anyhow!(
1036	                    "unknown doc-values kind {kind}"
1037	                )))
1038	            }
1039	        };
1040	        out.insert(name, column);
1041	    }
1042	    Ok(out)
1043	}
