482	fn pack_u32_block_v2(values: &[u32; BLOCK_SIZE], output: &mut Vec<u8>) {
483	    use bitpacking::BitPacker;
484	    let min = *values.iter().min().unwrap_or(&0);
485	    let max = *values.iter().max().unwrap_or(&0);
486	    let spread = max - min;
487	
488	    if spread == 0 {
489	        output.push(0u8);
490	        vbyte_encode(min, output);
491	        return;
492	    }
493	
494	    let num_bits_framed = (32 - spread.leading_zeros()) as u8;
495	    let num_bits_raw = (32 - max.leading_zeros()) as u8; // 1..=32, max > 0 here
496	    let (min, num_bits) =
497	        if num_bits_framed < num_bits_raw || num_bits_raw <= ZPS2_FOR_MAX_EQUAL_WIDTH {
498	            (min, num_bits_framed)
499	        } else {
500	            (0, num_bits_raw)
501	        };
502	    output.push(num_bits);
503	    vbyte_encode(min, output);
504	
505	    let mut lanes = [0u32; BLOCK_SIZE];
506	    for (lane, &value) in lanes.iter_mut().zip(values.iter()) {
507	        *lane = value - min;
508	    }
509	    // bitpacking::BitPacker4x::BLOCK_LEN == 128; byte_len is derived on read.
510	    let byte_len = BLOCK_SIZE * num_bits as usize / 8;
511	    let mut compressed = vec![0u8; byte_len];
512	    bitpacking::BitPacker4x::new().compress(&lanes, &mut compressed, num_bits);
513	    output.extend_from_slice(&compressed);
514	}
