516	/// Decode a 128-element block previously written by `pack_u32_block_v2`.
517	/// Reads the cursor forward past the data and fills `out`.
518	fn unpack_u32_block_v2(
519	    data: &[u8],
520	    cursor: &mut Cursor<&[u8]>,
521	    out: &mut [u32; BLOCK_SIZE],
522	) -> io::Result<()> {
523	    use bitpacking::BitPacker;
524	    let num_bits = cursor.read_u8()?;
525	    let min = vbyte_decode(cursor)?;
526	    if num_bits == 0 {
527	        *out = [min; BLOCK_SIZE];
528	        return Ok(());
529	    }
530	    if num_bits > 32 {
531	        return Err(io::Error::new(
532	            io::ErrorKind::InvalidData,
533	            "postings block: invalid bit width",
534	        ));
535	    }
536	    let byte_len = BLOCK_SIZE * num_bits as usize / 8;
537	    let start = cursor.position() as usize;
538	    let end = start + byte_len;
539	    if end > data.len() {
540	        return Err(io::Error::new(
541	            io::ErrorKind::UnexpectedEof,
542	            "postings data truncated",
543	        ));
544	    }
545	    bitpacking::BitPacker4x::new().decompress(&data[start..end], out, num_bits);
546	    for value in out.iter_mut() {
547	        *value = value.wrapping_add(min);
548	    }
549	    cursor.set_position(end as u64);
550	    Ok(())
551	}
