705	/// Decodes a variable-byte `u64` from `cursor`.
706	pub fn uvarint_decode(cursor: &mut Cursor<&[u8]>) -> io::Result<u64> {
707	    let mut result = 0u64;
708	    let mut shift = 0u32;
709	    loop {
710	        let byte = cursor.read_u8()?;
711	        result |= ((byte & 0x7F) as u64) << shift;
712	        if byte & 0x80 != 0 {
713	            return Ok(result);
714	        }
715	        shift += 7;
716	        if shift >= 70 {
717	            return Err(io::Error::new(
718	                io::ErrorKind::InvalidData,
719	                "uvarint overflow",
720	            ));
721	        }
722	    }
723	}
