726	/// many delta-encoded positions.
727	fn decode_position_group(cursor: &mut Cursor<&[u8]>) -> io::Result<Vec<u32>> {
728	    let count = vbyte_decode(cursor)? as usize;
729	    let mut positions = Vec::with_capacity(count);
730	    let mut prev = 0u32;
731	    for _ in 0..count {
732	        let delta = vbyte_decode(cursor)?;
733	        prev += delta;
734	        positions.push(prev);
735	    }
736	    Ok(positions)
737	}
