294	/// Parse and structurally validate a bundle's footer + trailer.
295	///
296	/// Returns the footer and the byte offset the footer starts at. Does NOT
297	/// recompute per-file CRCs — [`unpack`] does, on the write path, where a
298	/// mismatch must abort before any file lands.
299	pub fn parse_footer(bytes: &[u8]) -> Result<(BundleFooter, usize)> {
300	    let total = bytes.len();
301	    if total < BUNDLE_TRAILER_LEN + 4 {
302	        return Err(StorageError::Backend(format!(
303	            "bundle too short ({total} bytes) to carry a footer"
304	        )));
305	    }
306	    let trailer = &bytes[total - BUNDLE_TRAILER_LEN..];
307	    if &trailer[12..] != BUNDLE_MAGIC {
308	        return Err(StorageError::InvalidMagic {
309	            expected: BUNDLE_MAGIC,
310	            actual: trailer[12..].to_vec(),
311	        });
312	    }
313	    let version = u32::from_le_bytes(trailer[8..12].try_into().unwrap());
314	    if version != BUNDLE_FORMAT_VERSION {
315	        return Err(StorageError::UnsupportedVersion(version as u16));
316	    }
317	    let footer_start = u64::from_le_bytes(trailer[..8].try_into().unwrap()) as usize;
318	    let footer_len = u32::from_le_bytes(
319	        bytes[total - BUNDLE_TRAILER_LEN - 4..total - BUNDLE_TRAILER_LEN]
320	            .try_into()
321	            .unwrap(),
322	    ) as usize;
323	    let footer_end = total - BUNDLE_TRAILER_LEN - 4;
324	    if footer_start >= footer_end
325	        || footer_len != footer_end - footer_start
326	        || footer_end.checked_sub(footer_start).is_none()
327	    {
328	        return Err(StorageError::Backend(format!(
329	            "bundle trailer is inconsistent: footer_start={footer_start}, \
330	             footer_len={footer_len}, object_len={total}"
331	        )));
